const knowledge = [
{"id": "4.1", "lesson": 4, "n": 1, "page": 11, "title": "神经多样性：从缺陷视角转向差异视角", "answer": "神经多样性（Neurodiversity）把人类脑功能差异视为自然且有价值的变异。资料把ASD、ADHD 和读写障碍放在认知功能谱系中理解。概念由 Judy Singer 于 20 世纪 90 年代末提出。缺陷模型着重病理、症状、矫正和标准化；差异模型着重优势、接纳、包容和环境适配。", "plain": "先理解这个人怎样学习、有什么需要和优势，再设计支持。", "words": "Neurodiversity · Judy Singer · 缺陷模型 · 差异模型", "source": "L4 第 2 页"},
{"id": "4.2", "lesson": 4, "n": 2, "page": 11, "title": "为什么跨诊断研究：共病、共享机制与遗传基础", "answer": "把 ASD、ADHD、读写障碍和 OCD 一起研究，依据是共病率高、遗传风险及分子和神经回路存在重叠、跨诊断研究有助于超越标签。资料列遗传度约 40%–80%。多数情况涉及许多微小效应的常见变异 SNPs，少数案例涉及 CHD8、SCN2A 等高影响稀有变异。基因多效性（Pleiotropy）指一个基因影响多种表型；GWAS 显示不同状况可共享风险位点。", "plain": "一个标签不能包办全部机制，同一种遗传影响也可能出现多种表现。", "words": "共病 · 多基因 · SNPs · CHD8 · SCN2A · Pleiotropy · GWAS", "source": "L4 第 3–4 页"},
{"id": "4.3", "lesson": 4, "n": 3, "page": 11, "title": "三类共享分子机制：突触、基因表达和免疫", "answer": "（1）突触功能：SHANK3、NRXN1、NLGN3/4 参与突触结构与功能，变异可影响形成、成熟和修剪；E/I 失衡假说关注兴奋与抑制信号失衡。（2）染色质重塑：CHD8、ARID1B、SETD1A 调控基因表达，影响神经元分化、迁移和回路形成的时间。（3）免疫相关过程：小胶质细胞、星形胶质细胞及 C1q、C3 参与突触修剪；异常激活可能带来过度或不足的修剪。", "plain": "要记三件事：连接怎样建、基因何时开关、连接怎样修剪。", "words": "E/I 失衡假说 · 染色质重塑 · 小胶质细胞 · C1q · C3", "source": "L4 第 4–5 页"},
{"id": "4.4", "lesson": 4, "n": 4, "page": 12, "title": "三条细胞信号通路：mTOR、Wnt/β-catenin、PI3K-AKT", "answer": "mTOR 整合内外信号，调控细胞生长、增殖和代谢；资料把其过度激活与神经元体积、蛋白合成及 LTP/LTD 失衡联系起来。Wnt/β-catenin 参与神经元迁移、极性建立和皮层分层。PI3K-AKT 位于 mTOR 上游，支持存活、生长和抵抗凋亡，并影响树突、突触及网络效率。多条通路相互作用，可形成不同而重叠的表现。雷帕霉素的例子是动物模型中的治疗潜力。", "plain": "这三条通路分别帮助理解生长调控、发育组织和生存支持，彼此会互动。", "words": "mTOR · Wnt/β-catenin · PI3K-AKT · Rapamycin · LTP · LTD", "source": "L4 第 6–7 页"},
{"id": "4.5", "lesson": 4, "n": 5, "page": 12, "title": "风险基因的作用有时间和位置差异", "answer": "资料按四阶段说明时空特异性：孕中期 CHD8 等 ASD 风险基因与皮层基本模式形成有关；产后和婴儿期突触发生、修剪密集，遗传与环境共同塑造连接；儿童期 DRD4 等与较晚成熟的注意及执行网络有关；青春期和成年期回路继续修剪、精细化，部分特征可能更明显或缓解。", "plain": "同一个发育影响，发生在什么时间、哪个脑区，会改变结果。", "words": "时空特异性 · 孕中期 · DRD4 · 遗传与环境", "source": "L4 第 8 页"},
{"id": "4.6", "lesson": 4, "n": 6, "page": 12, "title": "精准神经多样性与神经指纹", "answer": "精准神经多样性（Precision Neurodiversity）希望用 fMRI、DTI、图论和机器学习描述个体差异。功能连接组（Connectome）可由静息态 fMRI 中各脑区活动同步性构建，资料称其为神经指纹（Neural Fingerprint）。资料举例：FPN 与 DMN 分离度关联流体智力，注意网络连接关联持续注意，感觉皮层与高级联合皮层的连接梯度关联感觉敏感性。", "plain": "同一诊断不等于同一张脑网络图，因此支持方案需要考虑个人差异。", "words": "Precision Neurodiversity · Connectome · rs-fMRI · Neural Fingerprint", "source": "L4 第 8–9 页"},
{"id": "4.7", "lesson": 4, "n": 7, "page": 12, "title": "生物学亚型：诊断名称相同，神经特征仍可能不同", "answer": "生物学亚型（Biotypes）是依据神经生物学特征进行的分层，目的是辅助诊断、预测预后和匹配干预。资料列举两种 ADHD 亚型：延迟大脑生长型，全脑灰质体积较小、成熟模式较幼；产前大脑生长异常型，总体积正常或偏大，但 DMN 等网络连接异常。资料提出，两型可能需要不同策略和预后判断。", "plain": "同样叫 ADHD，也可能是不同的发育轨迹。", "words": "Biotypes · 异质性 · 延迟大脑生长 · 产前大脑生长异常", "source": "L4 第 10 页"},
{"id": "4.8", "lesson": 4, "n": 8, "page": 13, "title": "认知功能与脑网络的对应表", "answer": "资料把执行功能对应到额顶网络 FPN 和扣带–岛盖网络 CON；社交认知对应到 DMN和镜像神经元系统；注意调节对应到背侧注意网络 DAN 与腹侧注意网络 VAN；感觉处理对应到感觉皮层与突显网络 SN。复习时还要把每组网络与资料列出的异常连接模式配对，不能只背缩写。", "plain": "记住“什么能力—哪些网络—出现什么变化”这一整组。", "words": "FPN · CON · DMN · DAN · VAN · SN", "source": "L4 第 11 页"},
{"id": "4.9", "lesson": 4, "n": 9, "page": 13, "title": "三步分层决策框架及 Z 分数", "answer": "第一步，多模态初步评估：量表、神经心理测试、家长教师报告、发育环境资料，加上 T1、rs-fMRI 和 DTI。第二步，与年龄匹配常模比较，依据模块化、全局效率和节点中心性等计算偏差。第三步，按分层匹配支持。资料原表为低偏差 Z<1、中度 1<Z<2、高度 Z>2；等于1 或 2 未写明。该表是本课介绍的框架。", "plain": "先收集行为和脑数据，再看相对常模的偏差，最后讨论支持方式。", "words": "多模态评估 · 常模 · Z 分数 · 模块化 · 节点中心性", "source": "L4 第 11–13 页"},
{"id": "4.10", "lesson": 4, "n": 10, "page": 13, "title": "精准应用的研究、伦理和落地障碍", "answer": "方法上：可重复性不足要用预注册、开放数据代码和标准流程；数据泄露要用严格交叉验证；分析师自由度要用多重比较校正和效应量报告。伦理上：保护脑数据隐私和知情同意，防止学校、雇主或保险中的歧视，避免新生物学标签制造等级。落地还需纵向验证、多模态整合、低成本工具、临床培训及政策支持。", "plain": "能画出脑图，不等于已经有可靠、可负担又公平的决策工具。", "words": "可重复性 · 数据泄露 · 交叉验证 · 分析师自由度 · 知情同意 · 神经歧视", "source": "L4 第 14–15 页"},
{"id": "4.11", "lesson": 4, "n": 11, "page": 13, "title": "神经可塑性的三种形式与 Hebb、LTP、LTD", "answer": "神经可塑性指大脑根据经验改变连接、适应和重组自身的能力。突触可塑性是连接强弱变化；结构可塑性是树突、突触及神经元等结构变化；功能可塑性是区域间功能承担的重组。Hebb 理论强调共同激活的神经元连接会加强。LTP 是连接持久增强，LTD 是连接减弱；资料把二者分别与学习记忆、遗忘及网络优化相联系。", "plain": "可塑性既包括连接更强或更弱，也包括结构和功能组织的改变。", "words": "突触可塑性 · 结构可塑性 · 功能可塑性 · Hebb · LTP · LTD", "source": "L4 第 17 页"},
{"id": "4.12", "lesson": 4, "n": 12, "page": 14, "title": "可塑性的案例怎样支持定义", "answer": "结构例子包括树突生长、突触发生和成人海马神经发生；资料引用 Eriksson 等（1998）。功能重组的例子是中风后健康脑区协助承担受损功能。Draganski 等（2004）的杂耍案例报告练习三个月后视觉运动相关灰质体积增加，停止练习后回落，用来说明用进废退；“灰质体积改变”本身属于结构指标。资料还用双语者讨论持续经验与执行网络的关系。", "plain": "看案例先问：测的是连接强度、脑结构，还是功能承担方式？", "words": "Eriksson 1998 · Draganski 2004 · 成人神经发生 · 功能重组 · 用进废退", "source": "L4 第 18 页"},
{"id": "4.13", "lesson": 4, "n": 13, "page": 14, "title": "学习的认知过程与神经网络", "answer": "认知心理学把学习组织为编码、存储和提取。神经层面，PFC 支持注意与工作记忆，海马体支持记忆形成和巩固，杏仁核参与情绪显著性与动机。资料把 Hebb、Piaget 建构主义、Kolb 经验学习、Mezirow 转换学习和认知负荷理论，分别联系到连接强化、主动探索、练习反思、认知重构和工作记忆限制。", "plain": "学习需要注意、记住、理解和提取，多种脑系统一起参与。", "words": "编码 · 存储 · 提取 · PFC · 海马体 · 杏仁核 · Piaget · Kolb · Mezirow", "source": "L4 第 19 页"},
{"id": "4.14", "lesson": 4, "n": 14, "page": 14, "title": "认知负荷与可塑性的倒 U 型关系", "answer": "按资料，负荷过低容易无聊，不能充分调动学习；负荷过高会超过工作记忆容量，并引发压力和表现下降；适中的挑战最有利。课件报告 DLPFC 激活强度与负荷相关 r=0.67，强调最优区间的效率。答题要说明“适合当前能力的挑战”，不能把负荷增加直接等同于学习变好。", "plain": "题目太容易没挑战，太难会装不下；关键是把难度调到能努力完成。", "words": "倒 U 型 · 工作记忆容量 · 最优负荷 · DLPFC · r=0.67", "source": "L4 第 20 页"},
{"id": "4.15", "lesson": 4, "n": 15, "page": 14, "title": "四种学习策略：间隔、交叉、主动回忆、合作", "answer": "间隔重复：分时重新激活记忆，巩固长期保持。交叉学习：混合不同主题，促进区分和迁移，减少成块练习带来的假熟悉。主动回忆：通过测试练习提取，即 Testing Effect。合作学习：通过讨论、教别人促进理解和保持。资料称主动回忆比被动重读效率高 50%以上，复习时把它当作该页所报告的数值。", "plain": "复习不只看懂：还要隔一会儿再想、混着辨别、合上书提取、讲给别人。", "words": "间隔重复 · 交叉学习 · 主动回忆 · Testing Effect · 合作学习", "source": "L4 第 21 页"},
{"id": "4.16", "lesson": 4, "n": 16, "page": 15, "title": "终身学习、补偿性可塑性与认知储备", "answer": "资料用成人再培训后的 DTI 白质变化支持终身学习。补偿性可塑性指某区域或回路受限时，其他回路增强功能以提供支持；教育例子包括读写障碍的颜色编码、思维导图，ASD 的低感官刺激和结构化视觉支持。认知储备指通过教育、持续学习和解决问题形成较高效的回路，帮助抵御老化或病理影响。策略有新知识、社交、脑力挑战和有氧运动。", "plain": "补偿强调怎样帮助当前薄弱功能；储备强调长期积累应对衰退的能力。", "words": "Li 2023 · DTI · 补偿性可塑性 · 认知储备 · BDNF", "source": "L4 第 20–22 页"},
{"id": "4.17", "lesson": 4, "n": 17, "page": 15, "title": "正念、自适应平台与 VR/AR 的课程解释", "answer": "正念：资料引用 Tang 等（2020），联系到压力皮质醇、杏仁核反应、PFC–杏仁核连接和岛叶自我觉察。自适应平台按“表现输入—实时分析—难度调整—保持最优负荷”循环工作，资料引用 Dimitriadis 等（2021）说明认知灵活性与额顶效率。VR/AR 用于多感官参与、提高动机及安全场景模拟，如手术和飞行训练。", "plain": "三类做法分别关注注意情绪、难度适配和体验设计。", "words": "正念 · Tang 2020 · 自适应平台 · Dimitriadis 2021 · VR/AR", "source": "L4 第 23–24 页"},
{"id": "4.18", "lesson": 4, "n": 18, "page": 15, "title": "神经迷思、增强伦理与教育未来", "answer": "资料反对“只用 10%的脑”和把人固定分为左脑型、右脑型学习者。认知增强涉及公平、儿童发育安全、长期影响及人格创造力等问题。未来方向是整合 AI 自适应和 VR/AR、提高教师神经科学素养、通过政策支持公平的终身学习。五项回顾是终身可塑、学习改变脑、用进废退、最优挑战和个体差异。", "plain": "懂脑的目的，是更合理地设计学习与支持，而不是给每个人贴脑型标签。", "words": "神经迷思 · 认知增强 · 教育公平 · 神经科学素养 · 个体差异", "source": "L4 第 25–27 页"},
{"id": "4.19", "lesson": 4, "n": 19, "page": 15, "title": "tDCS 是什么，典型实验怎样设计", "answer": "经颅直流电刺激 tDCS 通过微弱直流电调节神经元兴奋性；资料列通常 1–2 毫安。典型设计为招募、基线认知测试、随机分组、刺激结合任务、即时及追踪测试。双盲使研究者和参与者都不知道分组。假刺激控制外观与感觉，但不持续通电，用来控制安慰剂等影响。", "plain": "要比较刺激是否有效，必须有可比较的基线、分组和假刺激条件。", "words": "tDCS · 1–2 mA · 随机分组 · 双盲 · 假刺激", "source": "L4 第 27–28 页"},
{"id": "4.20", "lesson": 4, "n": 20, "page": 16, "title": "tDCS 案例：激活更低为什么可能表现更好", "answer": "资料报告相同高负荷任务下，真刺激组 DLPFC 激活较低、与顶叶连接较强而表现较好；正确率提高约 12%，反应时间缩短约 130 毫秒，部分效果持续数小时至数天。神经支持假说解释：当额顶资源趋近上限，tDCS 提高 DLPFC 基准兴奋性，帮助维持处理效率，从而以较少激活代价完成任务。这是对案例的机制解释。", "plain": "判断效率要同时看脑反应和任务表现，不能只说越亮越好。", "words": "神经支持假说 · 神经效率 · 12% · 130 毫秒 · 额顶网络", "source": "L4 第 28–30 页"},
{"id": "4.21", "lesson": 4, "n": 21, "page": 16, "title": "tDCS 为什么不能假定人人同样获益", "answer": "资料指出，基线工作记忆较低者获益较明显；基线较高者可能无明显改善，甚至被干扰，强调基准状态与个体差异。应用设想包括特殊教育、高技能训练、康复和老龄化。局限包括教育公平与知情同意，电极位置、强度、时长缺少统一方案，颅骨厚度影响电流，以及重复使用的长期安全性和效果仍需纵向研究。", "plain": "同一种刺激用在不同的人和任务上，结果可能不同。", "words": "基线能力 · 个体差异 · 倒 U 型效应 · 标准化 · 长期效果", "source": "L4 第 29–31 页"},
{"id": "4.22", "lesson": 4, "n": 22, "page": 16, "title": "T1、fMRI、DTI 和 EEG 分别看什么", "answer": "T1 看脑体积与皮层厚度；fMRI 通过 BOLD 血氧变化间接测神经活动，可做任务态或静息态，局限包括秒级时间分辨率、高费用和运动敏感；DTI 依据水分子扩散观察白质纤维微结构；EEG 用头皮电极记录神经元群体电活动，具有毫秒级时间分辨率，可分析 ERP 及Delta、Theta、Alpha、Beta、Gamma 频段。", "plain": "结构、连接、血氧活动和电活动是不同测量，不能混作同一张脑图。", "words": "T1 · fMRI · BOLD · DTI · EEG · ERP", "source": "L4 第 12 页、21、32–33"},
{"id": "4.23", "lesson": 4, "n": 23, "page": 16, "title": "TMS 和 tDCS 怎样区分", "answer": "TMS 用线圈磁场在脑内诱发电流，可暂时激活或抑制目标区域，可用于研究某区域的因果作用，资料也提到抑郁症治疗。tDCS 用皮肤电极输入微弱直流电，调节静息膜电位；资料概括为阳极提高、阴极降低兴奋性，同时强调个体差异大、标准方案仍在探索。两者均属于调控技术，不是记录脑活动的 EEG。", "plain": "TMS 靠磁场诱发电流；tDCS 通过电极施加弱直流电。", "words": "TMS · tDCS · 静息膜电位 · 因果研究", "source": "L4 第 33 页"},
{"id": "4.24", "lesson": 4, "n": 24, "page": 17, "title": "附录中的人物与研究资源怎样配对", "answer": "资料列神经多样性人物 Judy Singer、Simon Baron-Cohen 和 Thomas Armstrong；可塑性人物 Michael Merzenich、Eleanor Maguire 和 Richard Davidson。分别关联概念提出、ASD 极端男性脑理论、教育应用、可塑性及 BrainHQ、伦敦出租车司机海马研究、正念情绪研究。机构有 NIMH、MRC 和 Simons Foundation；资源有 Dana Foundation、INSAR 及 Learning How to Learn。", "plain": "人名题用“姓名—代表主题”配对记忆，别把所有人都背成提出可塑性。", "words": "Singer · Baron-Cohen · Armstrong · Merzenich · Maguire · Davidson · NIMH · MRC", "source": "L4 第 31–35 页"},
{"id": "4.25", "lesson": 4, "n": 25, "page": 17, "title": "认知储备的附录证据与数字", "answer": "资料引用 Snowdon（2001）修女研究：早年写作的语言复杂性较高，与晚年较慢认知衰退有关。附录还称双语者认知症状平均晚出现 4–5 年，教育保护效应约 40%，规律有氧活动每年估计降低认知衰退风险约 7%。这些是课件给定表述；回答应保留研究情境，不能改写成任何个人都必然获得同样效果。", "plain": "储备讲的是长期经历与抵御衰退的关系；数字要连同资料情境一起记。", "words": "Nun Study · Snowdon 2001 · Bialystok · 4–5 年 · 40% · 7%", "source": "L4 第 34 页"},
{"id": "5.1", "lesson": 5, "n": 1, "page": 24, "title": "诊断标签、RDoC 与任务选择偏差", "answer": "资料指出，DSM 行为诊断存在机制异质性和高共病。NIMH 提出的研究领域标准RDoC 按认知系统、社会过程、正负效价等维度连接基因到行为，也回应合并为连续谱（Lump）或区分机制（Split）的争论。比较 ADHD 与 ASD 时，若前者多研究抑制、后者多研究社会情绪，差异可能混入任务差异，因此要在相同维度配对比较。", "plain": "要判断两组脑反应是否不同，先尽量让他们面对可比较的任务。", "words": "DSM · RDoC · 共病 · 任务选择偏差 · 合并与区分 · NIMH · Lump · Split", "source": "L5A 第 1–3 页"},
{"id": "5.2", "lesson": 5, "n": 2, "page": 24, "title": "Tamon 等（2024）：怎样研究共同与特异神经异常", "answer": "资料列筛选 20,756 篇文献，纳入 243 项任务态 fMRI 研究、12,533 人。依 RDoC 分层配对任务与效应方向，进行 10,000 次随机均衡子抽样 ALE，用全脑聚类水平 FWE 校正p<.05。核心结论是控制任务选择偏差后，ASD 与 ADHD 的特异异常多于共享异常。共享机制不意味着两者应合成一个诊断。", "plain": "先平衡任务再比较，结果仍显示两组既有相同点，也有更明显的不同点。", "words": "Tamon 2024 · 243 · 12533 · ALE · 10000 · FWE · 特异性", "source": "L5A 第 3 页、6"},
{"id": "5.3", "lesson": 5, "n": 3, "page": 24, "title": "共有与特异脑区：高活化、低活化不能记反", "answer": "共有高活化：右舌回、右直回；共有低活化：左额中回 MFG、左颞上回 STG。ASD特异高活化：左颞中回 MTG、左顶下小叶 IPL；低活化：左 MFG；ACC 依任务呈双向异常。ADHD 特异高活化：右脑岛、后扣带 PCC；低活化：右苍白球、左额下回 IFG。资料将这些结果联系到感觉、执行、社会加工、显著性和抑制等功能。", "plain": "先记共同的两高两低，再分别记 ASD 和 ADHD 的特异模式。", "words": "舌回 · 直回 · MFG · STG · MTG · IPL · ACC · 脑岛 · PCC · 苍白球 · IFG", "source": "L5A 第 4–6 页；L5B 第 4 页"},
{"id": "5.4", "lesson": 5, "n": 4, "page": 25, "title": "Le Cunff 等（2024）：认知负荷的多模态研究", "answer": "该范围综述按资料共 67 项研究，群体占比 ADHD61%、ASD21%、读写障碍 18%；图中技术分布为 EEG52%、fMRI33%、fNIRS9%、眼动 6%。典型负荷增加伴随 Theta 功率升高、Alpha 功率抑制，工作记忆资源枯竭可伴随 P300 波幅下降。典型 BOLD 额顶反应随负荷增加，特殊群体可能出现低负荷过度反应或高负荷调节不足。", "plain": "不同工具从电活动、血氧和眼动等角度观察任务占用了多少资源。", "words": "Le Cunff 2024 · 67 项 · EEG · fMRI · fNIRS · 眼动 · 负荷调节", "source": "L5A 第 7 页；L5B 第 7–8 页"},
{"id": "5.5", "lesson": 5, "n": 5, "page": 25, "title": "读写障碍：定义、连接组视角与 Lou 研究设计", "answer": "资料定义为智力正常、教育机会充分时，字词准确辨识与拼读流畅度仍持续困难，并列患病率 5%–10%。研究视角从局部 VWFA、颞顶语音区，转向白质连接。Lou 等（2019）纳入 26 名读写障碍儿童和 31 名对照，平均年龄 11.61 与 11.49 岁，前者阅读年龄落后至少 18 个月；使用 3T、60 扩散方向、CSD 追踪、AAL90 节点和 90×90 加权矩阵，结合 NBS 与图论。", "plain": "除了看某个区域，还要看阅读所需的区域之间能否顺畅协作。", "words": "Lou 2019 · VWFA · 连接综合征 · DTI · CSD · AAL · NBS", "source": "L5A 第 8–9 页"},
{"id": "5.6", "lesson": 5, "n": 6, "page": 25, "title": "读写障碍的左侧 8 节点、7 边子网络", "answer": "NBS 找出左枕–颞–顶 8 节点、7 边的较弱子网络，FWE 校正 p=.023。正文列背侧语音流 ROL.L–INS.L–SMG.L–STG.L，腹侧正字法流 MOG.L–MTG.L–TPOsup.L；图内另标赫氏回 HES.L，合计 8 节点。子网 FA 图示障碍组.41、对照.47，差异 F(1,55)=6.935，p=.011；全脑 FA 两组均.44，p=.804。局部差异不能写成全脑所有白质均受损。", "plain": "关键是特定阅读网络连接较弱，而全脑平均值未出现同样差异。", "words": "8 节点 · 7 边 · 背侧语音 · 腹侧正字法 · HES.L · FA · 局部特异性", "source": "L5A 第 9–10 页"},
{"id": "5.7", "lesson": 5, "n": 7, "page": 25, "title": "小世界、整合与分离：四个图论指标", "answer": "小世界结合高局部聚类和较短路径，S=(C/C_rand)/(L/L_rand)>1。资料显示两组在12%–26%稀疏度区间均保留小世界特征。GE 衡量远距离脑区之间信息并行传输，属于全局整合；CC 衡量相邻节点互联密度；LE 衡量局部子网容错和专门处理；T 为传递性，反映模块内连接品质。CC、LE、T 对应局部组织或分离。", "plain": "GE 像看跨区交流；CC、LE、T 像看一个小组内部怎样协作。", "words": "Small-World · S>1 · GE · CC · LE · T · 整合 · 分离", "source": "L5A 第 11 页"},
{"id": "5.8", "lesson": 5, "n": 8, "page": 26, "title": "识字相关与回归增量：两种统计问题", "answer": "L5A p.12 图示识字相关 r：LE=.70、CC=.69、GE=.69、T=.62；各项统计经 FDR 处理。分层回归另回答增加预测信息多少：基础模型 R²=.453；加入 IFOF 与 SLF II 偏侧化指标增加 25.5%解释量；CC 和 LE 各再增加 7.2%，GE 增加 6.5%。相关系数 r 与增量 ΔR² 不是同一指标，不能把.69 解释成额外解释 69%。", "plain": "“两项一起变化多强”和“加进模型后多解释多少”是两个问题。", "words": "r · R² · ΔR² · FDR · IFOF · SLF II", "source": "L5A 第 12–13 页；L5B 第 15 页、19"},
{"id": "5.9", "lesson": 5, "n": 9, "page": 26, "title": "读写障碍的基因与脑电线索", "answer": "资料列 DYX1C1、DCDC2、KIAA0319 与神经元迁移及轴突生长有关；SLC2A3 与葡萄糖运输及左弓状束 FA 相关；ROBO1 参与轴突导向，并关联胼胝体微结构和阅读行为。脑电方面，工作记忆和解码任务中 P300 较低，Theta 可向右半球偏移，课件解释为对左语音回路的代偿；Lotfi 等（2020）的训练后 P3 回升被用作可塑性例子。课件把 Theta 右移称为“大细胞系统缺陷理论”的代偿性电生理线索。", "plain": "这部分把遗传、白质连接和任务中的电活动串起来，但它们不是同一种证据。", "words": "DYX1C1 · DCDC2 · KIAA0319 · SLC2A3 · ROBO1 · P300 · Theta · Lotfi 2020 · 大细胞系统缺陷理论", "source": "L5A 第 13–14 页；L5B 第 8 页"},
{"id": "5.10", "lesson": 5, "n": 10, "page": 26, "title": "ADHD 的病因与认知异质性", "answer": "资料列学龄儿童患病率 8%–12%，约 65%症状可持续至成年；仅 50%–60%在敏感执行功能测试中出现明确异常。遗传度估计约 70%，范围 60%–80%，涉及多巴胺、去甲肾上腺素及血清素相关基因、小效应常见变异和稀有 CNVs。G×E 例子是 DAT1 9R 或 DRD4 7R 叠加孕期烟雾暴露，课件引 Neuman 等（2007）报告混合型风险达 9 倍。", "plain": "ADHD 有多种成因和表现，不能假定每个人都在同一种测试上困难。", "words": "Luo 2019 · 异质性 · 遗传度 · CNV · G×E · DAT1 · DRD4", "source": "L5A 第 14–15 页"},
{"id": "5.11", "lesson": 5, "n": 11, "page": 26, "title": "ADHD 的年龄、性别和气质亚型", "answer": "资料图示过动冲动随年龄下降，注意力不集中问题较持续；诊断率示例为男童 12%、女童 4.7%，安静的注意缺陷表现容易漏识别。Karalunas 等（2014）依据 PEP 等自主神经指标和情绪特征分三型：温和型 Mild，情绪调节较正常；冲动探索型 Surgent，高趋近和活动；易怒型 Irritable，高负性情绪，并见杏仁核–脑岛连接减弱及未来 ODD/CD 风险约两倍。", "plain": "同一个诊断还要看年龄变化、情绪特点及是否容易被观察到。", "words": "Mild · Surgent · Irritable · Karalunas 2014 · PEP · ODD/CD", "source": "L5A 第 16 页"},
{"id": "5.12", "lesson": 5, "n": 12, "page": 27, "title": "ADHD：双通路模型与 Barkley 抑制模型", "answer": "Sonuga-Barke（2003）双通路模型区分背侧认知路线与腹侧动机路线：DLPFC–纹状体参与工作记忆及抑制；OFC–腹侧纹状体/伏隔核等参与奖赏与延迟厌恶。Barkley（1997）把行为抑制放在基础位置，再影响非语言工作记忆、语言内化、情绪–动机自我调节和行为重建，进而影响目标导向行为。", "plain": "一种模型区分“认知控制”和“等待奖赏”；另一种追问抑制不足怎样连带影响执行功能。", "words": "Sonuga-Barke 2003 · 双通路 · 延迟厌恶 · Barkley 1997 · 行为抑制 · 四项次级功能", "source": "L5A 第 17 页"},
{"id": "5.13", "lesson": 5, "n": 13, "page": 27, "title": "ADHD：CSTC 环路与认知–能量模型", "answer": "CSTC 为皮质–纹状体–丘脑–皮质环路。资料列 PFC/ACC 发育延迟和低活化、尾状核/壳核体积与多巴胺转运体异常、丘脑过滤干扰不足。Sergeant（2000）的认知–能量模型CEM 强调喚醒、活化、努力等能量状态不能按任务需要调节。慢事件速率可能使喚醒下降，提高刺激频率和即时奖赏可改善参与；这是对情境依赖性的解释。", "plain": "有时问题不只是“会不会做”，还包括能否把状态调到适合任务。", "words": "CSTC · PFC · ACC · 纹状体 · 丘脑 · CEM · Sergeant 2000 · 事件速率", "source": "L5A 第 18–19 页"},
{"id": "5.14", "lesson": 5, "n": 14, "page": 27, "title": "ADHD：发育双重分离与工作记忆亚群", "answer": "Halperin 与 Schulz（2006）区分相对静态的皮质下缺陷和动态的前额叶代偿；青春期后缓解与 PFC/ACC 成熟有关。N-back 从 0 到 3 增加负荷时，资料描述部分 ADHD 的DLPFC、VLPFC 及纹状体募集不足。但 Mattfeld 等（2016）区分工作记忆保留与受损亚群；Valera 等（2010）报告男性与女性的激活模式也不同。因此，不能把低活化套给所有 ADHD个体。", "plain": "群体平均差异下面，还藏着工作记忆正常的人和不同的发展路线。", "words": "Halperin & Schulz 2006 · 静态皮质下 · 动态前额叶 · N-back · Mattfeld 2016 · Valera 2010", "source": "L5A 第 19–21 页"},
{"id": "5.15", "lesson": 5, "n": 15, "page": 27, "title": "ASD 认知灵活性与 Lage 元分析", "answer": "认知灵活性指根据变化切换任务、策略并调整行为。维度转换四步是掌握规则、接到变化反馈、抑制旧规则、提取并切换新规则。资料从 Damasio 与 Maurer（1978）的额叶损伤类比谈起，并列 3–5 岁下 PFC 发展。Lage 等（2024）纳入 59 项研究、4,158 人，ASD2,122人、对照 2,036 人，年龄 4–85 岁，排除 IQ<70 并做 IQ 匹配；总体是小至中度困难且有明显异质性。", "plain": "转换困难不只是没听懂新规则，还可能卡在停用旧规则和启动新规则。", "words": "认知灵活性 · Set Shifting · Damasio & Maurer 1978 · Lage 2024 · 59 项 · 4158 · 异质性", "source": "L5B 第 1–2 页"},
{"id": "5.16", "lesson": 5, "n": 16, "page": 28, "title": "WCST、固执性错误、年龄与 ACC", "answer": "WCST 同时调用工作记忆、抑制与规则归纳，资料将其列为较敏感范式；IED 有未达标准即终止的机制，可能低估困难。固执性错误 PE 指已收到旧规则错误的明确反馈，却继续用旧规则；其效应较突出，而维度外转换错误未显著。年龄在元回归中不是显著调节变量。课件用ACC 冲突监控解释：社会情绪任务高活化，奖赏及转换任务低活化，错误预警不足可能妨碍转换。", "plain": "最要会辨认的错误是：规则已变、反馈也到了，却仍反复用旧办法。", "words": "WCST · IED · PE · 固执性错误 · 年龄调节 · ACC · 冲突监控", "source": "L5B 第 3–4 页"},
{"id": "5.17", "lesson": 5, "n": 17, "page": 28, "title": "三种理解 ASD 灵活性困难的理论", "answer": "单聚焦 Monotropism：有限注意高度投入一个目标，产生深度专注和细节优势，但强行切换代价大。弱中央统合 Weak Central Coherence：偏重局部信息，有利于细节任务，却可能不易把握全局规则。贝叶斯预测编码解释：感觉输入权重偏高、先验预期较弱，容易高估环境波动，追求同一性可成为降低不确定性的保护策略。三者是不同解释角度。", "plain": "可以分别从注意怎么分、信息怎么整合、变化怎么预测来理解。", "words": "Monotropism · Murray 2005 · 弱中央统合 · Happé & Frith 2006 · Hypo-priors · Pellicano & Burr 2012 · Lawson 2017", "source": "L5B 第 5–6 页"},
{"id": "5.18", "lesson": 5, "n": 18, "page": 28, "title": "ASD 的焦虑、重复行为与工作记忆负荷", "answer": "资料列焦虑共病约 40%，将部分重复刻板行为 RRBs 解释为在突变或过载时自我安抚、降低自主神经喚醒。教育上可先预告、提供结构化日程并降低不确定性。工作记忆方面，资料描述高难度下额顶活化不能继续增加，即 Failure of Load Modulation；言语工作记忆还可呈右额叶偏侧化，课件解释为非典型代偿。", "plain": "遇到摇晃、坚持程序或抗拒变化时，要同时考虑负荷、不确定性和焦虑。", "words": "40% · RRBs · Self-soothing · 负荷调控不足 · 右偏侧化", "source": "L5B 第 6–7 页"},
{"id": "5.19", "lesson": 5, "n": 19, "page": 28, "title": "EEG 与 ERP：Theta、Alpha 和 P300", "answer": "典型负荷增加时，Theta（4–8Hz）升高，Alpha（8–12Hz）受抑即 ERD。资料列ADHD 反应不稳定且编码时 Alpha 调节异常，ASD 缺少正常随负荷变化的调控，读写障碍Theta 右侧化。P300 是刺激后约 300 毫秒的正向波，与注意投入和工作记忆更新有关；综述中ADHD8 项有 7 项、读写障碍 4 项有 3 项报告 P3 较低。训练后 P3 回升被用作可塑性线索。", "plain": "频段看持续节律，P300 看刺激后的特定时间反应，两者不能混作一项。", "words": "Theta 4–8Hz · Alpha 8–12Hz · ERD · P300 · 7/8 · 3/4", "source": "L5B 第 7–8 页；L5A 第 7 页、14"},
{"id": "5.20", "lesson": 5, "n": 20, "page": 29, "title": "瞳孔与眨眼：外周指标怎样提示负荷", "answer": "资料将瞳孔变化联系到 LC–NE 系统、喚醒和心智努力：读写困难儿童读相同段落时扩张较大；ADHD 例子是最初 5 秒扩张、其后 20 秒缩小。眨眼与基底核及多巴胺有关；资料列放松约 15–20 次/分钟，视觉专注时下降，过载后可能反弹或目光漂移。它们提供状态线索，仍需考虑任务和测量干扰。", "plain": "看眼动是在观察任务中的状态变化，不能只凭一次眨眼多就判定某种障碍。", "words": "LC–NE · 瞳孔 · 心智努力 · 眨眼率 · 15–20 次/分钟 · 基底核", "source": "L5B 第 9–10 页"},
{"id": "5.21", "lesson": 5, "n": 21, "page": 29, "title": "测量有效性与儿童舒适不能分开", "answer": "三类干扰是头动伪影、瞳孔透视误差 PFE 和药物效应。资料列对策：下颌托或眼镜式眼动仪、视线角度校正、研究中的用药状态分组或洗脱期设计。数据例子包括 ASD 眼动约 14%因运动脱落、fNIRS 中 105 名 ADHD 有 34 人因不适退出。全纳研究还应考虑轻量电极、模拟扫描环境熟悉训练和静音 MRI，不能以数据密度牺牲儿童舒适与安全。", "plain": "设备测到的变化，可能来自任务，也可能来自动作、视线、药物或不舒服。", "words": "Motion Artifacts · PFE · 药物混淆 · 14% · 34/105 · Mock Scanner · 伦理", "source": "L5B 第 10 页"},
{"id": "5.22", "lesson": 5, "n": 22, "page": 29, "title": "三类认知负荷与课堂过载表现", "answer": "内在负荷来自内容复杂度并受先验知识影响，可用分解和知识桥接调节。外在负荷来自不良呈现、噪声等无效干扰，应减少。相关负荷是图式建构和理解的有益努力，应支持。资料举过载表现：ADHD 晃动离座或打断，ASD 捂耳摇晃或回避，读写障碍指读停滞、视线游离或揉眼；这些应与任务及生理状态一起理解。", "plain": "先减少不必要的干扰，再把学生的有限资源留给理解。", "words": "Intrinsic · Extraneous · Germane · 先验知识 · 图式 · 过载", "source": "L5B 第 11 页"},
{"id": "5.23", "lesson": 5, "n": 23, "page": 29, "title": "读写障碍的课堂支持：外显、分段与多感官", "answer": "资料提出背侧语音路线用明确的音位拆解和拼读规则；正字法方面用大字、颜色标词根词缀。也可结合图形、Text-to-Speech 和实体教具，增大行字距、以短段和重点提示减轻持续维持负担。VAKT 依次是看字形、听字音、手空书或沙盘描写、触摸凸字。课件还举无衬线字体和米黄背景；这些是其教学建议，不能把脑关联结果自动说成已验证每项建议。", "plain": "把隐含规则讲清楚，让学生能看、听、做，并一次处理较短内容。", "words": "外显教学 · 音位 · 正字法 · TTS · 分段 · VAKT", "source": "L5B 第 12 页、14–15"},
{"id": "5.24", "lesson": 5, "n": 24, "page": 30, "title": "ADHD 的课堂支持：节奏、运动与即时反馈", "answer": "课件依据 CEM 设计 15 分钟微讲授、2 分钟身体微休息、10 分钟互动练习和即时反馈。具体做法有语调变化和动态呈现、允许安静捏捏乐或脚底弹力带及站立、即时视觉代币或成就反馈。CCN 由 DLPFC 及顶下小叶支持外部任务；DMN 由 PCC 及内侧额叶等参与内部思考。资料用 DMN 侵入解释部分走神，把支持目标放在状态与投入的维持。", "plain": "把长时间等着听改成有节奏的参与，并及时告诉学生进展。", "words": "CEM · 15–2–10 · 即时增强 · CCN · DMN · PCC", "source": "L5B 第 12 页、15–16"},
{"id": "5.25", "lesson": 5, "n": 25, "page": 30, "title": "ASD 的课堂支持：预告、外部提示和兴趣", "answer": "资料建议固定位置放视觉日程，在转换前 5 分钟及 1 分钟预告，设置安静角落、降噪耳机和柔和光线。用绿进行、黄准备、红切换的信号，或明确口头提示，提供外部转换支架；每次只变一个变量。依据单聚焦，把特殊兴趣变成学习载体，例如用火车时刻表学习数学、阅读和历史时间轴。", "plain": "先让变化可预期，再提供清楚的切换提示，并借用学生投入的兴趣。", "words": "视觉日程 · 5 分钟/1 分钟 · Quiet Corner · 外部监控 · 单变量 · 特殊兴趣", "source": "L5B 第 13 页、16–17"},
{"id": "5.26", "lesson": 5, "n": 26, "page": 30, "title": "共病、跨诊断支持与 UDL 三原则", "answer": "资料列 ASD 伴 ADHD 约 28%–44%，ADHD 与读写障碍共病 25%–40%；共同的执行和工作记忆需要可支持跨诊断环境设计。UDL 三原则是多种表征、多种行动与表达、多种参与。L5B p.18 将其分别对应后部识别、前部战略、深部情感网络。这是本页的课程表述；其“精确对齐”的证据强度需与第 6 课对神经宣传的讨论一起核对。", "plain": "可以按共同学习需要设计支持，同时保留个别化调整。", "words": "共病 · 跨诊断支持 · UDL · 表征 · 行动与表达 · 参与", "source": "L5A 第 2 页、6；L5B 第 13 页、18；L6A 第 9–14 页"},
{"id": "5.27", "lesson": 5, "n": 27, "page": 30, "title": "异质性、神经迷思与拒绝神经决定论", "answer": "资料用 ADHD 气质与工作记忆亚群、ASD 效应异质性、读写能力连续谱反对单一教案。它也反对左脑理性右脑感性的简单分类和固定视觉/听觉/动觉学习者标签；多感官教学不等于给每人固定一种风格。神经决定论把当前脑图当成发展命运；资料主张脑仍可改变，教育应改善环境并支持潜能，不能据影像放弃学生。", "plain": "脑图帮助理解当前困难，但不能替学生宣布以后只能怎样。", "words": "异质性 · 连续谱 · 神经迷思 · 学习风格 · Neuro-essentialism · 可塑性", "source": "L5B 第 17–19 页"},
{"id": "5.28", "lesson": 5, "n": 28, "page": 31, "title": "五篇核心研究各负责回答什么", "answer": "Tamon 等（2024）：ADHD 与 ASD 任务态 fMRI 的共同和特异模式。Le Cunff 等（2024）：ADHD、ASD 和读写障碍认知负荷的神经生理测量综述。Lou 等（2019）：读写障碍白质网络连接及图论。Luo 等（2019）：ADHD 异质性、神经认知模型与发育。Lage 等（2024）：ASD 认知灵活性的元分析。先按问题记研究，再记方法和数字，避免把 Lou 与 Luo混为一篇。", "plain": "这五篇分别是脑区比较、负荷测量、阅读连接、ADHD 差异和 ASD 转换。", "words": "Tamon · Le Cunff · Lou · Luo · Lage", "source": "L5A 第 1 页；L5B 第 19–20 页"},
{"id": "6.1", "lesson": 6, "n": 1, "page": 40, "title": "全纳教育为何从“学生适应学校”转向“学校适应学生”", "answer": "资料引用 Opertti 等（2014），把发展脉络分为：1948 年教育权利；1990 年代特殊教育需要与 1994 年《萨拉曼卡宣言》；2000 年前后关注种族、语言、贫困等边缘群体；2005年后推动教育系统整体改革。批评“一刀切”教学，是因为它假设存在一个平均学生，容易忽视学习困难者与资优学生。全纳强调主动改变制度、环境和课程，使不同学生都能参与。", "plain": "先改课程里挡住学生的地方，不能一看到差异就把学生排除出去。", "words": "全纳教育 · 教育权利 · 系统改革 · 平均学生", "source": "L6A 第 2 页"},
{"id": "6.2", "lesson": 6, "n": 2, "page": 40, "title": "UDL：提前设计多条进入学习的路径", "answer": "通用学习设计（Universal Design for Learning, UDL）借鉴 20 世纪 80 年代建筑通用设计，资料以坡道和自动门为例；教育框架由 CAST 的 Rose 与 Meyer 等发展。核心把障碍放在课程设计与学习者的互动中。三原则：多元表征（Representation，学什么），如文字、音频、图像与动画；多元行动与表达（Action and Expression，怎样展示学习），如书写、打字、语音转文字、绘画与口述；多元参与（Engagement，为什么愿意学），如选择、适当挑战与动机支持。", "plain": "同一个学习目标，可以有不同的理解方式、回答方式和参与方式。", "words": "UDL · 表征 · 行动与表达 · 参与 · 主动设计", "source": "L6A 第 3 页"},
{"id": "6.3", "lesson": 6, "n": 3, "page": 40, "title": "DI：依据正在发生的学习差异调整教学", "answer": "差异化教学（Differentiated Instruction, DI）由 Tomlinson 相关研究系统发展，资料提及 1999、2001 与 2014 年，背景包含资优教育与混合能力班。调整依据包括准备度（readiness）、兴趣（interest）和学习概况（learning profile）；调整对象包括内容（content）、过程（process）和成果（product）。教师通过持续的形成性评估了解学生，再调整任务、支架和组织方式。DI 不等于给某些学生永久发简单练习。", "plain": "先看学生现在会什么、卡在哪里，再决定怎样教、给多少帮助。", "words": "DI · 准备度 · 兴趣 · 学习概况 · 内容—过程—成果 · 形成性评估", "source": "L6A 第 4–5 页"},
{"id": "6.4", "lesson": 6, "n": 4, "page": 41, "title": "Griful-Freixenet 综述：UDL 与 DI 并没有一种公认关系", "answer": "资料介绍的系统综述检索 5 个数据库，共纳入 27 项研究，其中 8 项实证、19 项理论研究。归纳三种关系：互补（complementary）37%；嵌入（embedded）48%，占比最高；不相容（incompatible）15%。这些百分比描述所纳入文献的关系分类，不是三种课堂模式的成效排名。资料同时提醒，UDL 不是随意让学生选择，DI 也不是降低对一部分学生的期待。", "plain": "研究者有三种说法，最多人把 DI 看成 UDL 大框架里面的具体做法。", "words": "27 项 · 8 项实证 · 19 项理论 · 37% · 48% · 15%", "source": "L6A 第 5 页"},
{"id": "6.5", "lesson": 6, "n": 5, "page": 41, "title": "互补、嵌入与不相容，各自怎样理解", "answer": "互补观点：UDL 在课前主动设计，处理全班共同可能遇到的障碍；DI 在课中根据形成性评估作响应，处理更具体的个人差异。嵌入观点：UDL 是外层框架，DI 是内部实践；资料以 Katz（2013）三模块举例，包含社会情绪学习共同体、全纳教学实践（结合 DI 和逆向设计UbD）、结构与政策支持。不相容观点关注两种风险：DI 可能变成固定能力分组，固化标签；UDL 若只有自由选择，可能缺乏对基线能力、进度和成效的追踪。", "plain": "两套方法可以配合，但分组不能把人定死，给选择也不能放弃检查学生学会没有。", "words": "课前主动 · 课中响应 · Katz 三模块 · 固定分组 · 进度追踪", "source": "L6A 第 6–8 页"},
{"id": "6.6", "lesson": 6, "n": 6, "page": 41, "title": "Boysen 要检验的是哪一个脑科学主张", "answer": "资料介绍 CAST 的三网络对应：情感网络—参与原则—边缘系统及腹侧前额叶；识别网络—表征原则—后部枕、顶、颞皮层；策略网络—行动与表达原则—额叶。Boysen 等（2025）审查的是这些精确对应与 UDL 指南的神经科学依据。审查从 1,909 条引文记录去除467 条重复，得到 1,442 条独立引文，覆盖 36 个检查点；由 4 名独立编码者及专家按神经科学相关性、研究类型和解剖对应进行编码。", "plain": "不是看到“大脑”两个字就算证据；要查文献有没有真正支持那条具体对应。", "words": "Boysen · 三网络对应 · 1909−467＝1442 · 36 个检查点 · 证据审查", "source": "L6A 第 8–9 页"},
{"id": "6.7", "lesson": 6, "n": 7, "page": 41, "title": "引文审查发现：引了文献，不等于验证了神经网络", "answer": "资料报告 1,442 篇引文中只有 16 篇与脑功能有客观关联，约 1%；27 个检查点，即75%，没有神经科学引文；47%的相关引文集中在检查点 2.1“符号与词汇”，“行动与表达”整条原则只有 1 篇。资料另列 68%的研究呈现广泛激活，21%（4 篇）符合 CAST 指定脑区，而 4 篇中 3 篇是理论评述。最后一组的计数与比例分母未说明，背诵时应按资料分项记，不能自行把它们换算成同一个样本。", "plain": "证据很少，还集中在少数地方；有脑区活动，也不代表三套网络能一一对应。", "words": "16 篇 · 约 1% · 27 个检查点 · 75% · 47% · 广泛激活", "source": "L6A 第 10 页"},
{"id": "6.8", "lesson": 6, "n": 8, "page": 42, "title": "直接支持、间接支持与“脑科学很有说服力”的陷阱", "answer": "资料把支持强度分为直接 5%、间接 74%、无支持或无关 21%；所谓直接支持只来自Hammond（2014）的通俗书。另一次 PsycINFO 检索由 51 条记录形成 40 篇独立文献，没有发现直接验证 UDL 神经机制的一手实证研究，3 篇属于手册类资料。资料还指出 CAST 更新后把前额叶放入三个网络，与早期只归入策略网络的做法存在张力。Seductive allure 指脑术语或漂亮脑图使解释显得更可信，但不能代替证据。", "plain": "“看起来很科学”和“真的被研究证明”是两件事。", "words": "直接 5% · 间接 74% · 无支持 21% · 40 篇 · 零一手验证 · Seductive allure", "source": "L6A 第 11–12 页"},
{"id": "6.9", "lesson": 6, "n": 9, "page": 42, "title": "批评 UDL 的神经依据，不等于否定所有 UDL 教学实践", "answer": "神经迷思是对脑知识的误解、过度简化或编造，资料举例 VAK 学习风格匹配、左脑／右脑型学生，以及把 UDL 三原则硬分成三个独立脑区。课堂中的选择、支架、多种表征可能具有认知或行为研究依据，但不能仅凭脑区解释认定有效。资料引用 Zhang 等（2024）称严格检验 UDL 学业效果的随机对照试验只有 6 项，主张清楚操作化教学行为、设置随机对照并使用标准化学习结果。", "plain": "可以保留有用做法，同时诚实承认它的脑科学说法还没有被充分验证。", "words": "神经迷思 · VAK · 6 项 RCT · 操作化 · 学业成效", "source": "L6A 第 13–14 页"},
{"id": "6.10", "lesson": 6, "n": 10, "page": 42, "title": "Astle 的跨诊断观点：为什么不能只按标签理解困难", "answer": "资料认为传统 DSM 分类有三类问题：诊断阈值带有任意性；同一诊断内部差异大；不同诊断之间大量重叠。列出的共病／交叠资料包括 ADHD 儿童中 44%伴学习障碍，ASD 儿童中约 75%有学习挑战（范围 65%–85%），ADHD 与 ASD 交叠约 50%（范围 30%–70%）。这些是资料所列不同研究范围，不能当作所有儿童的固定比例。只纳入“纯诊断”样本、排除共病，会削弱研究对真实课堂的解释力。", "plain": "一个标签不能把孩子的全部学习特点说清楚，不同标签的孩子也可能卡在同一项能力。", "words": "跨诊断 · 阈值 · 类别内异质性 · 类别间重叠 · 共病", "source": "L6A 第 15–16 页"},
{"id": "6.11", "lesson": 6, "n": 11, "page": 43, "title": "研究样本怎样从诊断标签转向实际困难", "answer": "资料比较三种研究取样：临床病例—对照；按功能困难转介；未经筛选的一般人群研究。后两者更能观察连续的认知差异与真实重叠，资料举 SCALES 约 7,000 名儿童和 TEDS。CALM 研究纳入约 800 名有实际学习困难的儿童，只有约三分之一具有 ADHD 诊断。进入支持系统的依据应包含实际功能需要，不宜把取得诊断作为唯一门槛。", "plain": "先问孩子实际需要什么帮助，再看标签，而不是没标签就不给帮助。", "words": "功能转介 · 一般人群 · SCALES · TEDS · CALM 约 800", "source": "L6A 第 16–17 页"},
{"id": "6.12", "lesson": 6, "n": 12, "page": 43, "title": "CALM 的三因素与跨诊断的五维度，要分开记", "answer": "CALM 资料总结三个认知因素：语音加工主要预测阅读；执行功能主要预测数学；加工速度与更广泛的学业表现相关。同页另列五个跨诊断困难维度：过度活跃／冲动、注意力分散、社交沟通障碍、执行功能受损、语音处理缺陷。五维度可以横跨 ADHD、ASD、阅读障碍、语言障碍或计算困难等不同诊断；它们不是 CALM 三个统计因素的另一种说法。 具体对应举例：冲动与注意困难可横跨 ADHD、ASD 及学习障碍；社交沟通是 ASD 核心维度，也可见于 ADHD 与语言困难；执行功能困难可涉及 ADHD、ASD 与数学；语音困难可见于阅读障碍、DLD 及注意问题。", "plain": "三因素是在归纳认知能力，五维度是在描述跨标签出现的困难，不要把两张表背成一张。", "words": "三因素 · 语音加工 · 执行功能 · 加工速度 · 五维度", "source": "L6A 第 17 页"},
{"id": "6.13", "lesson": 6, "n": 13, "page": 43, "title": "从脑网络、聚类到遗传：同样困难未必有同样起点", "answer": "资料介绍将儿童聚为 10 组的研究，每组仍混合 ADHD、ASD、OCD 及典型发展儿童，聚类不与诊断一一重合。全脑白质连接的图论指标，比只看单个脑区或局部纤维指标更有助于解释学业差异。遗传部分强调多基因小效应、一因多效及多基因风险评分（PRS）跨诊断关联；Seidlitz 所研究 8 类拷贝数变异（CNV）综合征呈现不同遗传起点汇聚到共享网络的现象。等终性（equifinality）指不同原因可通向相似功能结果，因此支持要看个体认知画像，避免“诊断遮蔽”。", "plain": "起点不同也能走到同一种困难，所以不能凭一个标签推断整套脑功能。", "words": "图论 · 白质网络 · 多基因 · 一因多效 · PRS · 等终性 · 诊断遮蔽", "source": "L6A 第 18–20 页"},
{"id": "6.14", "lesson": 6, "n": 14, "page": 43, "title": "Lotfi 的训练：视觉空间工作记忆与自适应支架", "answer": "资料介绍 Lotfi 等（2020），以 BrainWare Safari 训练阅读障碍儿童的视觉空间工作记忆（VSWM），任务包括网格位置回忆、迷宫路径与动态序列追踪。共 6 款游戏，记忆项从 1 个升至 6 个；成功才升级，失败不进阶，使难度贴近最近发展区（ZPD）。原文同时列“5周、30 次、约 30 小时、每次 55–65 分钟、每周 5 天”，其中日程与总次数不完全吻合，复习要保留原文并核对。", "plain": "任务会跟着表现变难，目标是让学生需要努力，又不至于一直失败。", "words": "Lotfi · VSWM · BrainWare Safari · 1 至 6 项 · 自适应 · ZPD", "source": "L6B 第 1–2 页"},
{"id": "6.15", "lesson": 6, "n": 15, "page": 44, "title": "Lotfi 样本与行为结果：近期认知提升、后期阅读变化", "answer": "准实验共 35 名 7–12 岁严重阅读困难儿童，平均约 8.2 岁，男女 26∶9；训练组 15人，等候对照组 20 人，非言语智商均值 95.2 与 96.9。评估在基线、训练后与 6 个月进行。资料报告注意力 d=1.22，F(1,33)=12.34，p<.001；反应控制 d=1.14，F=10.75，p<.01；1-back 由 28.2 升至 46.6，d=.96，p<.05。即时阅读增幅约 7%与 1.5%，组间未显著；6 个月后阅读理解 t(11)=−5.07，p<.001，综合阅读 t=−3.42，p<.05。资料据此强调延迟迁移与长期追踪。", "plain": "练完先在注意和记忆任务上看到变化，阅读理解的变化可能更晚才出现。", "words": "35 名 · 训练 15 · 对照 20 · 准实验 · 6 个月 · 延迟迁移", "source": "L6B 第 3–4 页"},
{"id": "6.16", "lesson": 6, "n": 16, "page": 44, "title": "ERP 怎样测，P3b 波幅和潜伏期各表示什么", "answer": "资料使用 21 导联、国际 10–20 系统、250 Hz 采样、0.3–50 Hz 滤波、−200 至 800 ms 分段，分析正确试次，在 Pz 位置观察 250–500 ms 的 P3b。资料把 P3b 解释为注意资源动员与工作记忆情境更新指标，以波幅讨论资源容量，以潜伏期讨论处理速度。训练组波幅4.90→7.43 μV，对照 4.97→3.76 μV；ANCOVA F(1,21)=4.25，p=.051，ηp²=.175；潜伏期约 370–390 ms，p=.52。资料称“增加 35%／显著”，但与同页数字存在口径冲突，不能省略该限制。", "plain": "波幅是在看反应有多强，潜伏期是在看反应什么时候出现；两者不能混着解释。", "words": "ERP · Pz · P3b · 250–500 ms · 波幅 · 潜伏期 · p=.051", "source": "L6B 第 4–5 页"},
{"id": "6.17", "lesson": 6, "n": 17, "page": 44, "title": "训练结果怎样与阅读联系：解释不能当成直接测量", "answer": "资料报告训练增益与 1-back 改善 r(15)=.58，p<.05；P3b 波幅变化与 WMTB-C 记忆综合得分变化 r(14)=.46，p=.07。它以“低层加工更省资源，释放资源支持理解”解释认知训练向阅读的延迟迁移，并举原来用 90%、后来用 30%、释放 70%的资源比喻。这些百分比不是本研究直接测得的资源分配量；第二个相关的 p=.07 也不能遗漏。教育启示是自适应支架、真实学习实践与持续评估，不能据此保证每个儿童都能立即提高成绩。", "plain": "作者提出一条可能的解释链：基础任务省力后，才有更多余力处理理解；不是已经把每一步都证实了。", "words": "相关 · r=.58 · r=.46 · p=.07 · 资源释放 · 解释链", "source": "L6B 第 6–7 页"},
{"id": "6.18", "lesson": 6, "n": 18, "page": 45, "title": "Rusconi 教师培训：四项能力与 20 小时设计", "answer": "资料用欧洲全纳教师档案（PIT）的四维度组织培训：重视学习者多样性，对应 SCCI思维量表；支持所有学习者，对应 TSR 教案与课堂可及性；与他人协同合作，对应协同教学日志；个人专业持续成长，对应 SAED 全纳自我效能。培训共 20 小时，16 小时线下、4 小时线上，五模块依次涉及全纳与神经科学基础、情感／记忆及识别网络、执行功能及策略网络、UDL 教案打磨、微格演练。这里的脑区映射是培训内容陈述，与前半课 Boysen 的批判应按所问文献分别回答。", "plain": "不只让教师记脑知识，还要改教案、练课堂、练合作，并检查实际变化。", "words": "Rusconi · PIT 四维度 · SCCI · TSR · SAED · 20 小时", "source": "L6B 第 7–8 页"},
{"id": "6.19", "lesson": 6, "n": 19, "page": 45, "title": "教师研究的样本与思维、教案变化", "answer": "瑞士提契诺州准实验有 51 名全纳教师，占当地相关教师约 45%；培训组 20 名、对照31 名；培训组 75%有特教背景，平均教龄约 13 年。SCCI 组别主效应 F=24.24，p<.001，时间×组别 F=4.46，p=.040，η²=.09；3 个月后线性时间效应 F=7.74，p=.012。TSR 教案样本N=42，均分 2.35→3.28，U=432.50、Z=−3.65；视频样本 N=18，2.23→3.28、Z=−3.73。盲评的五项为目标、障碍、表征、参与、表达，每项 1–4 分。资料解读为思维与可及性设计改善。", "plain": "有没有学会全纳教学，要看教师怎样设计和怎样上课，不能只问培训满不满意。", "words": "51 名 · 20／31 · 3 个月 · SCCI · TSR 五维度 · 盲评", "source": "L6B 第 9–10 页"},
{"id": "6.20", "lesson": 6, "n": 20, "page": 45, "title": "协同教学从一教一辅转向更平等的分工", "answer": "资料分析 39 名教师的协同教学日志，涉及 6 种模式。一教一辅的比例由 27%降至23.6%；一教一观察约 3%；平行教学由 8.5%升至 13.74%；站点教学约 14.78%。总体模式变化 χ²(6,N=1,684)=16.59。平行教学把全班分成两组，两名教师按同一教学计划分别教学；站点教学让学生在概念指导、多感官练习、独立任务等站点轮换。核心是让特教教师成为共同设计与授课的伙伴。", "plain": "两位教师都负责教学和支持，不是永远一位讲、另一位当助手。", "words": "协同教学 · 平行教学 · 站点教学 · 共同设计 · 伙伴关系", "source": "L6B 第 10 页、17"},
{"id": "6.21", "lesson": 6, "n": 21, "page": 45, "title": "自我效能为何会提升，也会回落", "answer": "SAED 自我效能时间×组别 F(1,48)=9.68，p=.003；教学策略维度 F=10.02，p=.003，学生参与维度 F=8.89，p=.005。3 个月后总体均值 7.05→6.84，p=.087，资料描述为回落趋势；持续性显著保留主要见参与维度（χ²(2)=6.73，p=.035；Z=−1.98，p=.048）。Bandura 四来源为掌握经验、替代经验、言语劝说、生理与情绪状态。资料区分较持久的认知／实践改变与易受班级压力影响的信心，提出同伴反思、持续导师支持和共同培训；资料称80%共同受训的双师搭档持续进行 UDL 教案迭代与复盘。", "plain": "会做一些新方法，不代表以后一直有信心；后续有人一起复盘和支持很重要。", "words": "SAED · Bandura 四来源 · 掌握经验 · 替代经验 · 言语劝说 · 情绪状态 · 持续支持", "source": "L6B 第 11–13 页"},
{"id": "6.22", "lesson": 6, "n": 22, "page": 46, "title": "把 UDL、DI 与跨诊断支持组合起来", "answer": "资料提出课前 UDL 先提供通用可及性，覆盖大部分需要（此处举 80%–90%）；课堂DI 依据表现补充支持（此处举最后 10%）。三层支持为 Tier 1 全班 UDL，Tier 2 针对能力弱项的小组支持，Tier 3 密集个别化支持。先设置字体、音频和不同支架入口，再在约 10 分钟后以形成性检查决定站点或任务调整。此处比例属于框架示例，不要与第七课 RTI 金字塔的 80%–85%、10%–15%、5%混用。", "plain": "先把课做得多数人都进得来，再看谁还需要额外一层帮助。", "words": "UDL＋DI · 三层支持 · 跨诊断 · 形成性检查", "source": "L6A 第 8 页；L6B 第 14–15 页；L7A 第 18–19 页"},
{"id": "6.23", "lesson": 6, "n": 23, "page": 46, "title": "支架、认知负荷与课堂节奏", "answer": "资料的支架撤除顺序是：给模板与步骤→逐步减少提示→开放任务与批判思考。表征采用文字配关键图示、需要时加音频，减少没有教学目的的装饰与重复。课堂节奏采用短输入、操作、讨论、总结，并安排 1–2 分钟脑休息、呼吸或身体活动。原文把高负荷持续时间写为 15–20 分钟，并给“40 分钟课＝10 分钟输入＋5 分钟操作＋10 分钟讨论＋5 分钟总结”；后者实际只列出 30 分钟，应按“分段和休息”的原则理解，不自行补出未提供的 10 分钟。", "plain": "先扶着做，再慢慢放手；把任务切开，也让学生有机会喘口气和整理信息。", "words": "支架撤除 · 模板 · 渐退 · 认知负荷 · 短时段 · 脑休息", "source": "L6B 第 15–16 页"},
{"id": "6.24", "lesson": 6, "n": 24, "page": 46, "title": "低干扰环境与三年级叙事课例", "answer": "环境支持包括视觉留白、减少杂乱、降低噪声、使用垫子／耳机、提供可预测的日程。资料以同时有阅读困难和注意困难的三年级叙事课为例：输入提供可访问文本、音频和重点标示；产出允许写作、故事图或口述；参与加入合作、约 15 分钟任务段及短休息。配合平行教学或站点教学，并用作品和课堂表现检查学生是否达成相同的核心目标。", "plain": "让学生把力气用在理解故事，而不是被字太密、声音太乱或只能手写这些障碍卡住。", "words": "低干扰 · 可预测 · 叙事课 · 多元产出 · 共同目标", "source": "L6B 第 17–18 页"},
{"id": "6.25", "lesson": 6, "n": 25, "page": 47, "title": "选教学方法时的三项证据检查", "answer": "资料列三项核查：第一，相关不等于因果，看到某脑区活动不能直接推出某教法有效；第二，提防 VAK 等学习风格匹配迷思，采用多种表征不是把学生固定成视觉型或听觉型；第三，检查是否有学习结果、随机对照试验或综合证据支持。全课五篇文献分工为：Griful-Freixenet 梳理 UDL 与 DI，Boysen 审查神经依据，Astle 提供跨诊断视角，Lotfi 讨论学生训练与 ERP，Rusconi 讨论教师培训和课堂变化。", "plain": "最后要回到学生到底学会了什么，以及证据能支持到哪一步。", "words": "相关不等于因果 · VAK · 学业结果 · 证据边界 · 五篇文献", "source": "L6B 第 14 页、18–20"},
{"id": "7.1", "lesson": 7, "n": 1, "page": 53, "title": "神经教育学与 NIES 的实践背景", "answer": "资料将神经教育学（Neuropedagogy）放在神经科学、认知心理学和教育的交汇处，主张理解学习中的脑变化，同时保留教师对课堂的专业设计。Friedman 等（2026）的背景是 Achva 学院约 8 年实践、约 200 名幼儿园及中小学教师，教龄约 3–12 年。教师被比喻为学习环境的“神经建筑师”；这一比喻强调有意识地设计经历，不表示教师能直接读取或操控每名学生的突触。", "plain": "脑研究提供一些理解学习的线索，教师把它变成学生能参与的教学安排。", "words": "神经教育学 · Friedman · Achva · 约 200 名 · NIES", "source": "L7A 第 1–2 页"},
{"id": "7.2", "lesson": 7, "n": 2, "page": 53, "title": "NIES：必须按顺序记住的四步骤", "answer": "NIES 全称为 Neuroscience Informed Educational Strategies。四步依次是：辨识神经原理→界定大脑功能属性→建立教学导向→发展课堂策略。资料以可塑性为例：先提出经验能改变连接；再明确练习、巩固和睡眠等功能属性；据此选择分散、主动、适度挑战与休息的取向；最后安排间隔练习、提取练习、交错练习和结构化微休息。图中学习改善是结果，不是第五步。", "plain": "先说依据是什么，再说它对学习意味着什么，最后才落到这节课怎么做。", "words": "NIES · 原则 · 功能属性 · 教学取向 · 具体策略", "source": "L7A 第 3–4 页"},
{"id": "7.3", "lesson": 7, "n": 3, "page": 53, "title": "可塑性、Hebb、STDP 与巩固：资料如何解释练习", "answer": "资料用长时程增强 LTP、长时程抑制 LTD、连接加强与精简说明经验如何影响神经连接，并强调新信息要连接已有知识。Hebb 原则为共同激活的神经元更易建立连接；STDP 强调激活先后与时间关系；“用进废退”提示持续、有意义的使用。睡眠中的慢波与 REM 过程参与巩固。课堂上不只是机械重复，而是让学生重述、画图、教同伴，并在最初 48 小时安排微复习。资料还以生长锥说明神经变化具有不同时间尺度，不能只追求立刻见效。", "plain": "重复要重新动脑、连接旧知识，并留时间巩固，不能等同于同一句话抄很多遍。", "words": "LTP · LTD · Hebb · STDP · 巩固 · 48 小时", "source": "L7A 第 3 页、5–6"},
{"id": "7.4", "lesson": 7, "n": 4, "page": 54, "title": "NIES 课堂例子与三项贡献", "answer": "资料把情绪与学习放在一起，强调好奇、探索、游戏和积极社会互动；例子包括以豆袋椅和安静玩具组成的赋能空间，以及地理寻宝游戏。一个课堂节奏是 10–15 分钟输入→低压力提取→2–3 分钟伸展或黏土活动。NIES 的三项贡献是使神经原则更精确、提供可重复使用的四步转译语法、要求同时对神经解释与教育成效负责。轻松有趣本身不是最终目标，仍需检查学生学到了什么。", "plain": "既照顾情绪和节奏，也把目标、做法和结果连起来检查。", "words": "情绪与学习 · 好奇 · 10–15 分钟 · 低压力提取 · 双重问责", "source": "L7A 第 4–7 页"},
{"id": "7.5", "lesson": 7, "n": 5, "page": 54, "title": "计算障碍与顶内沟 IPS：数感是本课重点", "answer": "资料把发展性计算障碍（Developmental Dyscalculia, DD）列为特定学习障碍，涉及数概念、基本算术事实、估算及数学推理，列出全球发生率约 5%–7%。顶内沟（Intraparietal Sulcus, IPS）是数量表征的核心区域。按资料的分工：右侧 IPS 较关联点阵、实物多寡等非符号表征与近似数量系统 ANS；左侧 IPS 较关联阿拉伯数字、运算符号等符号加工。资料同时呈现部分任务中过度活化、另一些任务中活化不足及灰质体积较低的研究，不能概括成所有 DD 任务都只有一种方向。", "plain": "数感困难不只是不熟乘法表，还可能涉及“多少”和数字符号之间的连接。", "words": "DD · 5%–7% · IPS · 右非符号 · 左符号 · ANS", "source": "L7A 第 8–9 页"},
{"id": "7.6", "lesson": 7, "n": 6, "page": 54, "title": "左角回 AG、代偿与超连接", "answer": "资料把左角回（Angular Gyrus, AG）与熟练算术事实提取相联；提取受阻时，儿童可能更多依赖 IPS 支持的逐一计数，例如用手指数。资料引 Michels 等（2018）描述训练前额、顶、视觉和颞叶之间的功能超连接（hyperconnectivity），将其解释为费力的代偿，不等于计算更有效率；数轴训练后超连接减少，活动变得较集中。这里比较的是特定研究的网络模式，不能仅凭“连接更多”或“连接更少”判断所有人的好坏。", "plain": "算术事实提不出来，就可能每次从头数；看起来很多区域都在忙，也可能表示做得很费力。", "words": "左 AG · 算术事实提取 · IPS 计数 · 超连接 · 数轴训练", "source": "L7A 第 10–11 页"},
{"id": "7.7", "lesson": 7, "n": 7, "page": 55, "title": "多感官、语言网络与数学应用题", "answer": "体感皮层处理触觉、压力、温度和本体感觉，资料用摸硬币、操作具体物件说明怎样给抽象数概念提供感官支点；联合皮层整合不同感官信息。应用题还需要语言与数量网络协同：按资料，韦尼克区（Wernicke）负责语义识别、语法解析和问题情境表征；布洛卡区（Broca）参与言语工作记忆、语法关系、内部语言计划与步骤组织。答题要说明“读懂题目”和“组织算术步骤”都可能影响应用题表现，不能只看会不会算。", "plain": "应用题要先读懂发生了什么，再想清楚按什么顺序算。", "words": "体感 · 联合皮层 · Wernicke · Broca · 应用题 · 跨网络", "source": "L7A 第 11–12 页"},
{"id": "7.8", "lesson": 7, "n": 8, "page": 55, "title": "遗传、共病和第二语言：不同困难会叠在一起", "answer": "资料以特纳氏综合征（Turner；原文一处写 Turne）及脆性 X 综合征说明数学困难可能与遗传及发展差异相关，用意是反对把困难一概归为不努力。资料又列约 65%的阅读障碍儿童存在计算缺陷或相关脆弱性，强调共享执行功能和视觉空间工作记忆弱项，共病可能增加困难。美国英语学习者（EL）超过 530 万，其中 76.4%以西班牙语为主要语言；EL 可能同时承担第二语言理解与数学处理负荷，因此需要语言及认知双重支架。这些数值均是资料所列范围，不能用来诊断个别学生。", "plain": "一个学生可能同时卡在数感、记忆和题目语言，支持要逐项看。", "words": "遗传易感 · 共病 · 65% · EL · 530 万 · 76.4% · 双重支架", "source": "L7A 第 12–13 页"},
{"id": "7.9", "lesson": 7, "n": 9, "page": 55, "title": "为什么脑研究不能直接变成一条课堂命令", "answer": "资料区分神经科学的描述性问题“发生了什么、怎样发生”和教育的规范性问题“应教什么、怎样安排才合适”。脑实验常研究毫秒级、受控任务，课堂涉及分钟、学期、发展过程与复杂社会环境。两者关系被类比为生物学之于医学、物理学之于建筑：基础知识有帮助，但不能替代专业实践判断。学校心理学家或相关特教协调角色被作为连接研究、评估与课堂的转译伙伴。", "plain": "知道一个脑机制，并不会自动告诉教师明天那一节课必须怎么上。", "words": "描述性 · 规范性 · 时间尺度 · 课堂情境 · 转译", "source": "L7A 第 14–16 页"},
{"id": "7.10", "lesson": 7, "n": 10, "page": 55, "title": "学校心理学家怎样搭桥：评估、转译和反向反馈", "answer": "资料给转译者三类任务：读懂技术研究并转成教师和家长听得懂的语言；依据数据参与 RTI、IEP 及支持决策；对商业“脑训练”和神经迷思把关，资料举有色滤镜宣传为例。转译应双向进行，课堂问题也要反馈为研究问题。Rotzer 等（2009）的例子把空间工作记忆、右IPS、岛叶与额下回的任务表现联系起来，再讨论旋转、拼图、数轴和具体操作的教学靶点。资料倡议研究学校（Research Schools），由教师提出真实问题、在专业支持下开展课堂 RCT，而非只接受外部研究结论。", "plain": "桥梁角色既要把研究讲明白，也要把老师真正遇到的问题带回研究端。", "words": "学校心理学家 · 数据决策 · 神经迷思把关 · 双向转译 · Research Schools", "source": "L7A 第 16–17 页、19–20"},
{"id": "7.11", "lesson": 7, "n": 11, "page": 56, "title": "RTI 三层支持：比例、强度和评估频率", "answer": "RTI 为干预反应模式。Tier 1 是全员普及预防，资料图示 80%–85%，提供高品质核心课程与通用筛查，评估每年 2–3 次，包含间隔、提取、交错练习及睡眠与运动支持。Tier 2是小组目标补充，10%–15%，提供针对性支架，图示每周评估，例子为每周 3–4 次小组自适应支持。Tier 3 是个别化密集干预，图示 5%，以 IEP 提供高强度支持，评估每日至每周。图中比例是框架示意，重点是支持强度和追踪随需要增加。", "plain": "先有全班好教学；仍有困难的人加小组帮助；再不够就加密集的个别计划。", "words": "RTI · Tier 1 · Tier 2 · Tier 3 · 80%–85% · 10%–15% · 5%", "source": "L7A 第 18–19 页"},
{"id": "7.12", "lesson": 7, "n": 12, "page": 56, "title": "DA 动态评估：要看学生在帮助下怎样学", "answer": "动态评估（Dynamic Assessment, DA）采用测验—教学—再测验（test–teach–test）。先看独立完成水平，再给有计划的提示、示范和支架，最后看改善情况；比较独立与支持后的表现，量化学习潜能（Learning Potential）与获益幅度（Gain Score）。它补充静态测验的一次性分数，目的是辨认哪种支架有效、学习潜能在哪里，为后续教学调整提供依据。", "plain": "不只问“现在会不会”，还问“给哪种帮助之后能学会多少”。", "words": "DA · test–teach–test · 独立表现 · 支架表现 · 学习潜能", "source": "L7B 第 1 页"},
{"id": "7.13", "lesson": 7, "n": 13, "page": 56, "title": "CRA 路径与五项数学教学支柱", "answer": "CRA 原图的三阶段为具象（Concrete）→半具象（Representational）→抽象（Abstract），也就是从实物到图示再到符号。先使用数棒、积木和实物，再用点、线、图形表示，最后进入数字和运算符号。资料列五项教学支柱：建立数感常规；多感官外显指导；视觉心理模型表征；同侪互教反馈；学生思维语言外显化，也就是把思考过程说出来。CRA 是表征推进的路径，与评估学生怎样响应帮助的 DA 不是同一框架。", "plain": "先摸得到、摆得出，再画得出，最后用算式表达。", "words": "CRA · 具体 · 表征 · 抽象 · 五支柱", "source": "L7B 第 2 页"},
{"id": "7.14", "lesson": 7, "n": 14, "page": 57, "title": "DSM 动态策略数学：把语言、算术和反思连起来", "answer": "本课 DSM 指 Dynamic Strategic Math（动态策略数学），资料引 Kong 与 Orosco（2016）及 Orosco（2014），面向文化和语言多样背景（CLD）且有数学困难的学生。教学整合词汇、阅读理解、算术策略、元认知与任务分块，使学生说清目标、步骤和检查方法。资料用前额叶控制网络与顶叶数量网络参与解释其可能机制，并将针对性训练与网络效率联系起来；这是教学解释，不宜把 DSM 三个字与临床诊断手册 DSM 混淆。", "plain": "让学生不仅做出答案，还能说出题目问什么、准备怎样算、为什么这样算。", "words": "DSM · Dynamic Strategic Math · CLD · 语言 · 元认知 · 分块", "source": "L7B 第 2–3 页"},
{"id": "7.15", "lesson": 7, "n": 15, "page": 57, "title": "Garcia 分数课：文化熟悉材料与渐进释放责任", "answer": "资料中的 Garcia 教师给 3–5 名英语学习者／有计算困难学生安排抽离式小组，以熟悉的墨西哥烤饼 quesadilla 学习分数。先教 whole、half、quarter、numerator、denominator 等词汇，配合齐读、画半份和四等份。应用题把整体分成 8 份，吃 3 份、给人 2份，剩 3/8。过程为明确剩余目标→确认以八等份为单位→标出 3 份和 2 份→数剩余 3 份。教师依次“我做 I do→我们做 We do→你们一起做 You do together→你独立做 You do alone”，逐步撤去支架。", "plain": "用熟悉的食物把词、图和算式接起来，再把解题责任慢慢交给学生。", "words": "Garcia · quesadilla · 3–5 人 · 3/8 · 渐进释放责任", "source": "L7B 第 3–6 页"},
{"id": "7.16", "lesson": 7, "n": 16, "page": 57, "title": "从困难画像写到 IEP：目标必须可观察", "answer": "资料的对应表包括：双侧 IPS／数感困难→每日约 5 分钟点阵比较与 Cuisenaire 彩色数棒；左 AG／事实提取困难→提取表和计算器支架；额顶网络／VSWM 负荷困难→大方格纸、减少一页题量、避免高压限时。IEP 目标示例为“使用 Cuisenaire 彩色数棒完成 10 以内数字分解，达成率 85%”。这些是按资料功能画像选择教学支持的例子，不能把课堂困难直接当作某个学生已经查明的脑区损伤。", "plain": "把“加强数学”改成学生能做什么、用什么帮助、做到多少就算达标。", "words": "IEP · 数感 · 事实提取 · VSWM · 10 以内 · 85%", "source": "L7A 第 19 页；L7B 第 6 页"},
{"id": "7.17", "lesson": 7, "n": 17, "page": 57, "title": "家校沟通有两个层次：教脑知识与按脑知识设计教学", "answer": "资料区分内容层面（content level），即向学生和家长解释脑可塑性与发展；设计层面（design level），即调整难度、环境、反馈和学习经历。Goldberg（2022）用“大脑是长达 25 年的建筑工地”作沟通隐喻，帮助家长容纳发展差异。另用三区模型说明需求与支持：舒适区是需求远低于资源；成长／伸展区是需求与支持匹配、接近 ZPD；压力区是需求远超资源。25 年是资料的沟通比喻，不宜答成每个人在 25 岁某天统一完成发育。", "plain": "一方面讲明白孩子还在发展，另一方面真的把任务调到他能在帮助下学到东西的位置。", "words": "内容层面 · 设计层面 · 建筑工地 · 舒适区 · 成长区 · 压力区 · ZPD", "source": "L7B 第 7–8 页"},
{"id": "7.18", "lesson": 7, "n": 18, "page": 58, "title": "神经多样性、成长型思维与数字刺激", "answer": "资料主张向家长说明可塑性，使用成长型思维支持练习，减少把困难归结为懒惰或固定能力。资料列约 20%人口具有神经多样性特征，并用数字平台“想要 wanting 增加、喜欢liking 下降”的表述讨论奖励刺激与持续追逐的风险，称为进化失配。家校应围绕儿童真实需要、学习节奏和支持展开讨论，不应仅以“天生如此”或“多练就一定正常”替代个别观察。", "plain": "承认差异，也给改变留空间；讨论具体学习和环境，不给孩子贴死标签。", "words": "可塑性 · 成长型思维 · 神经多样性 · wanting · liking · 进化失配", "source": "L7B 第 9 页"},
{"id": "7.19", "lesson": 7, "n": 19, "page": 58, "title": "动机与注意：SDT、DAN／VAN、CEN／DMN", "answer": "自我决定理论（SDT）强调胜任感、自治感和关联感；资料建议以小成功建立胜任感、给 2–3 种有意义选择、用同伴和师生关系支持归属。背侧注意网络 DAN 与自上而下、目标导向注意相联，腹侧注意网络 VAN 与自下而上的突发刺激捕获相联；中央执行网络 CEN 偏向外部任务，默认模式网络 DMN 与自我反思和意义建构相关。资料提出通过日记与反思平衡任务投入和内部理解，不把 DMN 简单当作无用走神。", "plain": "愿意学、能把注意拉回来、能想明白这件事和自己有什么关系，都需要照顾。", "words": "SDT · 胜任感 · 自治感 · 关联感 · DAN · VAN · CEN · DMN", "source": "L7B 第 10 页"},
{"id": "7.20", "lesson": 7, "n": 20, "page": 58, "title": "压力与创伤知情支持：先建立安全和可预测性", "answer": "资料用 HPA 轴与皮质醇讨论贫困、家庭冲突及羞辱性体验可能带来的持续压力，并与海马及前额叶学习功能相联系；家校沟通应减少责备，提出具体支持。创伤知情课堂的四项措施是：照顾营养、饮水与睡眠；提供稳定可预测的日程；设置可平静退避的空间；通过积极接纳的互动建立安全感。课堂观察用于发现支持需要，不应凭一次表现推断学生有创伤或某个脑区异常。", "plain": "先让学生知道这里安全、接下来会发生什么，才有余力投入学习。", "words": "压力 · HPA 轴 · 皮质醇 · 创伤知情 · 可预测 · 安全", "source": "L7B 第 11–12 页"},
{"id": "7.21", "lesson": 7, "n": 21, "page": 59, "title": "教师亲近性与评价方式怎样影响学习环境", "answer": "教师亲近性（immediacy）指用语言和非语言方式减少心理距离，资料举温暖目光、微笑、语气、适度幽默与开放姿态。评价侧重学习过程、低压力的多次尝试、允许纠错和个人成长曲线，减少只用排名评价学生。家校共同语言可以围绕“尚在发展”“目前需要什么支架”“这次比上次哪里进步”展开，让学习困难成为可讨论、可调整的问题。", "plain": "让反馈告诉学生下一步怎么做，而不是只告诉他排在别人后面。", "words": "immediacy · 心理距离 · 过程评价 · 低压力 · 成长曲线", "source": "L7B 第 12–13 页"},
{"id": "7.22", "lesson": 7, "n": 22, "page": 59, "title": "Thomas 调查：转译先要回应教师的现实负担", "answer": "资料介绍 Thomas 等（2024）通过 YouGov 调查 1,006 名教师。教师列出的主要现实问题为工作负担 42%、经费削减 19%、学生行为与情绪问题 13%。资料据此主张，教育神经科学转译要能帮教师解决现有困难和减少负担；如果只增加术语学习、备课或记录任务，即使理论吸引人，也难以在课堂持续实施。", "plain": "一套方案有没有用，也要看教师在真实工作条件下能不能持续做。", "words": "Thomas · YouGov · 1006 名 · 42% · 19% · 13% · 减负", "source": "L7B 第 14 页"},
{"id": "7.23", "lesson": 7, "n": 23, "page": 59, "title": "教师知道多少、想学什么：记清百分比的对象", "answer": "资料称约 33%的教师听说过教育神经科学；在知晓该领域的教师中，76%认为脑知识对教学有帮助。同页还列 71%认为相关专业发展、55%认为可在课堂实施、44%认为不可或缺，但没有清楚交代每张卡片的统计分母，不能自行都改写成“全部教师”。60%需要具体实践指南；最期待儿童脑发展阶段和特殊学习需要的策略。培训偏好为 CPD 在职进修 51%、实务工作坊 36%，提示转译需要可操作示例。", "plain": "这些教师更想知道明天怎么教，而不只是听一场很有道理的脑科学讲座。", "words": "33% · 知晓者 76% · 60%实践指南 · CPD51% · 工作坊 36%", "source": "L7B 第 15 页"},
{"id": "7.24", "lesson": 7, "n": 24, "page": 59, "title": "RCT、整体干预与教师判断：不能只背一个效应量", "answer": "资料引 Lortie-Forgues 与 Inglis（2019）：141 项教育 RCT 的平均效应量为.06，35%的项目为零或负效应；另引 Samani（2024）的整体干预效应量 1.58。两组来自不同证据，不能直接据此断言整体干预必然胜过 RCT 方案。资料讨论严格控制与真实课堂复杂情境之间的张力，并批评教师框架若只讲工作记忆、图式等认知内容，可能忽视情绪、社会关系与发展。科学应帮助理解“在什么情境对谁有效”，同时保留成效检验。", "plain": "既要查效果，也要看情境和学生；不能拿不同研究的两个数字直接判胜负。", "words": "141 项 RCT · .06 · 35% · 1.58 · 情境 · 认知与情绪", "source": "L7B 第 16–17 页"},
{"id": "7.25", "lesson": 7, "n": 25, "page": 60, "title": "反科学主义、转译枢纽与全课五篇文献链", "answer": "资料批评把科学包装成教师必须机械执行的标准指令，主张科学是反思工具（a tool for reflexivity），支持专业判断。借鉴 Catapult Hubs 的转译枢纽应连接大学脑科学实验室、中小学特殊教育教室、学校心理评估团队和教育政策部门，并纳入家长伙伴。五篇文献形成的课程链是：Friedman 的 NIES 原则转译→Wilcox 的 RTI／IEP 桥梁→Mamedova 与Orosco 的计算障碍／DSM 案例→Goldberg 的家校沟通→Thomas 的一线需求与政策反思。", "plain": "研究、课堂、评估和政策要能来回对话，家长也应一起参与解决实际学习问题。", "words": "科学主义 · 反思工具 · Catapult Hubs · 四方枢纽 · 家长伙伴 · 五篇文献", "source": "L7B 第 17–20 页"},
{"id": "8.1", "lesson": 8, "n": 1, "page": 66, "title": "AT 是什么：从低技术到高技术的连续谱", "answer": "辅助技术（Assistive Technology, AT）指用于增加、维持或改善障碍者功能能力的设备或产品系统，可以是市售、修改或定制的。资料强调可及性、平等参与、自主性、生活质量与社会正义。AT 包括低技术的握笔器、彩色覆盖片，中技术的语音输入、图形组织器，高技术的眼动控制、神经反馈等。UDL 在课程设计之初照顾多元需要，个别化 AT 补充特定功能支持；通用工具应能与 AT 兼容。 p.2 背景数字为全球约 2.4 亿儿童面临身心障碍、40%公立特教学校面临专业师资匮乏；按资料记忆，页内未说明后者的地域与统计口径。", "plain": "先问学生在哪一步被卡住，再找帮助他完成那一步的工具。便宜的握笔器和复杂的脑机接口都可能是 AT，价格高不等于更合适。", "words": "AT · 功能能力 · 连续谱 · 可及性 · UDL", "source": "L8A 第 2–3 页"},
{"id": "8.2", "lesson": 8, "n": 2, "page": 66, "title": "读写辅助工具与数字无障碍", "answer": "图形组织器用视觉—语义支架支持信息组织，按资料解释可减轻外在认知负荷与工作记忆压力。文字转语音（TTS）把文字转为听觉输入；语音转文字（STT）减轻书写输出负担；同步语音高亮帮助连接声音与文字。无障碍文件要使用真正的 H1–H3 标题层级，表格设置行列标题并避免合并单元格，图片提供替代文本或标记为装饰，链接文字应描述目的，多词标签采用#CamelCase。多媒体要减少冗余、配准确字幕、保证对比度；资料要求避免 3–30 Hz 闪烁。资料的机制对应为 TTS 绕过 VWFA 文字解码并利用左 STG 听觉语言通道，STT 减少运动皮层及 Exner 书写区负担，同步高亮支持角回的跨模态音形整合。", "plain": "输入困难用读出来的方式支持，输出困难用说出来的方式支持；排版也要让屏幕阅读器读得懂。不是把标题加粗就完成了无障碍。", "words": "TTS · STT · 同步高亮 · 替代文本 · 字幕", "source": "L8A 第 3–5 页"},
{"id": "8.3", "lesson": 8, "n": 3, "page": 67, "title": "SETT 与文化回应：为什么工具会被弃用", "answer": "SETT 依次考察 Student（学生）、Environments（环境）、Tasks（任务）、Tools（工具）。CEC-ISET 要求在四个维度都加入文化反思：学生语言与家庭价值；环境中的期望、设备和网络；任务是否符合文化与家庭目标；工具是否支持母语并避免污名。资料给出的AT 弃用率为 30%–50%，指出文化身份不匹配、集体主义家庭与极端独立目标冲突、AAC 口音不匹配及被标签化感受等都可能影响持续使用。", "plain": "不要从“买什么设备”开始。先弄清楚谁用、在哪里用、要完成什么，再选工具；好用还包括学生和家庭愿不愿意用。", "words": "Student · Environments · Tasks · Tools · 文化回应 · 30%–50%", "source": "L8A 第 5–6 页"},
{"id": "8.4", "lesson": 8, "n": 4, "page": 67, "title": "技术选择循环、DEI 与阅读课案例", "answer": "资料提出 Discuss（讨论）→Review（审查）→Explore（探索）→Alter &Advocate（调整与倡导）的技术选择循环。DEI 计划按 Vision（愿景）→Goals（目标）→Action Steps（行动步骤）→Continuous Feedback（持续反馈）推进，并纳入普教、特教、IT、家庭和学生。六年级双语历史小说案例同时考虑英语学习者、听障和读写障碍学生，以动态文字高亮、母语音频及邻近屏幕的手语支持减少信息切换。", "plain": "工具要先试、再看效果、再调整。一个班有多种需要，可以围绕同一个学习内容提供不同入口。", "words": "Discuss · Review · Explore · Alter & Advocate · DEI", "source": "L8A 第 7–8 页"},
{"id": "8.5", "lesson": 8, "n": 5, "page": 67, "title": "教育神经技术的五类及证据分布", "answer": "Nouri（2025）综述从 4,236 篇筛选出 471 项研究，界定教育神经技术为测量、分析或调节大脑活动以改善教与学的技术。五类是大脑结构与功能测量、神经反馈、非侵入物理神经调控、脑机接口、AI 赋能神经技术。图示研究类型为实验 210、相关 95、因果比较 88、文献综述 56、纵向 21、质性 1。认知领域 73%、认知与情感混合 20%、纯情感 7%；高等教育及典型发展群体居多，学前、中学、ASD 与多重障碍研究不足。", "plain": "先分清技术是在“看大脑”“让人依据反馈调节”“用电流调节”还是“把脑信号接到外部设备”。研究多不等于真实课堂的长期证据也多。", "words": "471 · 五大形态 · 纵向 21 · 质性 1 · 生态效度", "source": "L8A 第 8–10 页"},
{"id": "8.6", "lesson": 8, "n": 6, "page": 67, "title": "EEG、fNIRS 与超扫描", "answer": "EEG 具有毫秒级时间分辨率；fNIRS 通过血氧变化观察相关脑区活动，可用于前额叶认知负荷研究。两者较便于进入自然教学情境，但 EEG 受运动、肌电、导电膏和信噪比限制；fMRI、MEG 则受设备成本及运动限制。超扫描（Hyperscanning）同步测量教师与学生或同伴脑活动，资料举 EEG/fNIRS、Theta/Alpha 及相位锁定值（PLV）等指标，用于研究互动同步与即时记忆、理解的关系。", "plain": "一个人戴设备是看个人变化，多人同时测量是研究互动中的共同变化。“同步有关联”不能自动说成“同步直接造成学习进步”。", "words": "EEG · fNIRS · Hyperscanning · PLV · 信号噪声", "source": "L8A 第 11 页"},
{"id": "8.7", "lesson": 8, "n": 7, "page": 68, "title": "AI 融合与神经反馈分别做什么", "answer": "资料统计 60 项 AI 研究，将 CNN、SVM、Transformer 与 EEG、fNIRS 或行为数据结合，用于状态识别、预警与适应性反馈。Yu & Bai（2021）结合 EEG 与面部特征（LBP、SVM）进行情绪识别，资料报告准确率 85.7%。神经反馈则依据操作性条件作用，向学习者实时呈现脑活动信息，使其练习自我调节；资料举降低 Theta、提高 Beta 的 ADHD 训练例子。主要限制是伪迹、实验室结果的课堂迁移、标准化不足；评价须同时看科学有效性与教育相关性。", "plain": "AI 主要帮系统判断状态；神经反馈把状态反馈给学习者，让他练习调节。两者可以结合，但不是同一个概念。", "words": "多模态融合 · CNN · SVM · 操作性条件作用 · 科学有效性 · 教育相关性", "source": "L8A 第 12–13 页"},
{"id": "8.8", "lesson": 8, "n": 8, "page": 68, "title": "BCI 的定义、用途与硬件", "answer": "脑机接口（BCI）直接解码中枢神经系统信号并转化为机器指令，绕过外周神经与肌肉通路，为重度肢体障碍及无语言能力学生提供交互通道。资料综述含 19 项研究：非侵入式17/19（89.5%），侵入式 2/19（10.5%）。科研级例子为 64 导湿电极、超过 10,000 美元；消费级为 4–8 导干电极、300–1,200 美元。课堂选型要兼顾信噪比、可及性、舒适度与维护成本。", "plain": "BCI 的重点是把学生的意图或状态接到外部系统。它不是把知识直接装进大脑。", "words": "BCI · 中枢神经信号 · 非侵入式 89.5% · 干电极", "source": "L8A 第 14 页"},
{"id": "8.9", "lesson": 8, "n": 9, "page": 68, "title": "主动 BCI 与被动 BCI", "answer": "主动控制型（Active BCI）占资料所述研究的 84.2%，要求使用者有意识诱发活动，例如运动想象或注视目标字母，用于打字、轮椅或虚拟教具控制。被动监测型（Passive BCI）占 15.8%，在自然任务中隐式读取认知与情绪状态，用于调整学习节奏、难度和支持。资料的被动闭环例子为 EEG→前额 Theta/Alpha 比率上升→平台切换简化模式→负荷回到适当范围；Beauchemin 等研究报告后续测验提升 18%–25%。", "plain": "主动型是“我发出指令，设备替我做”；被动型是“系统观察我是否吃力，再调整材料”。", "words": "Active BCI · Passive BCI · 84.2% · 15.8% · Theta/Alpha", "source": "L8A 第 15 页、17"},
{"id": "8.10", "lesson": 8, "n": 10, "page": 69, "title": "P300、运动想象、语音 BCI 与长期稳定性", "answer": "P300 拼写器采用 Oddball 范式，目标刺激后约 300 ms 出现正向电位；Hoffmann等 5 名重度肢体障碍使用者中 4 人达到 100%拼写准确率，ITR 为 10–25 bits/min。EEG-Inception 研究报告相对传统算法的识别精度提升最高 16%。运动想象（MI）涉及对侧 ERD（Mu/Beta 能量下降）及同侧 ERS；资料分别报告健康者虚拟无人机任务 95.5%、混合现实机械臂 93.0%，不能混作普遍课堂成功率。Speech-BCI 包括默想语音解码及 N100 抑制/传出副本研究；新词分类例子约 65.7%。脑信号会因疲劳、注意及阻抗而漂移，需自适应校准；14 个月案例中运行时间 255→225 秒、准确率 46%→53%，另一 DNN 案例报告一年无重新校准仍>90%。", "plain": "三类技术分别寻找“注意了哪个目标”“想象了什么动作”“计划说什么”的信号。每个准确率都对应不同任务和样本，不能互换。", "words": "Oddball · P300 · ERD · ERS · Imagined Speech · 信号漂移", "source": "L8A 第 15–17 页"},
{"id": "8.11", "lesson": 8, "n": 11, "page": 69, "title": "BCI 进入课堂的关键：TPACK 与共同设计", "answer": "TPACK 要求整合技术知识（TK）、教学法知识（PK）和学科内容知识（CK）。19项 BCI 研究中 TK 为 100%（19/19），PK 为 5%（1/19），CK 为 11%（2/19），显示课程整合不足。VR-BCI 提供可控社交练习并监测压力；White 等大学年龄 ASD 案例支持可行性和耐受性，但行为结果存在个体差异，长期迁移仍需研究。维护中的电极校准可耗时 15–30 分钟。共同设计应采用干电极/柔性材料、符合 WCAG 的界面及自动校准；资料提出 2 分钟内完成启动的设计目标。 Badajena 等（2023）的特定轮椅控制案例报告，通过算法优化以 1/10 成本达到等效性能；这不是所有设备的通用降价比例。", "plain": "能准确控制设备只是第一关；还要说清楚它怎样帮助这节课的学习目标，老师是否能在课前用起来。", "words": "TPACK · TK100% · PK5% · CK11% · 共同设计", "source": "L8A 第 18–20 页"},
{"id": "8.12", "lesson": 8, "n": 12, "page": 69, "title": "tDCS 机制与系统评价证据", "answer": "经颅直流电刺激（tDCS）通过头皮电极输送低强度恒定电流，资料开篇范围为 0.25–1.5 mA；它调节静息膜电位，不直接引发动作电位。资料一般机制表述为阳极局部去极化、兴奋性增加和 LTP 样效应，阴极超极化、兴奋性降低和 LTD 样效应；后文另强调儿童非线性与反转情况。Salehinejad 等（2022）综述含 35 项 RCT、745 名儿童青少年，涉及 ADHD、ASD、读写障碍。18 项多疗程研究分为 ADHD 5 项、ASD 9 项、读写障碍 4 项，资料报告88.8%的多疗程改善率、8 项症状缓解及最长 6 个月维持。", "plain": "BCI 偏重读取信号和外部控制；tDCS 直接调节皮层兴奋性。这里背的是研究怎样做、报告了什么，不是自行使用的步骤。", "words": "tDCS · 静息膜电位 · 35 项 RCT · 745 人 · 88.8%", "source": "L8B 第 1–2 页；L8A 第 20 页"},
{"id": "8.13", "lesson": 8, "n": 13, "page": 70, "title": "tDCS 安全性与方法学局限怎样答", "answer": "综述所纳入 745 人累计 6,587 次刺激未报告严重不良事件；常见轻微反应为刺痛、瘙痒、温热感，资料称刺激结束后消退。特定耐受研究六点疼痛量表均值 0.94 分、86%愿再次参与。局限包括样本小、仅 13 项达到足够样本，只有 9/35（25.7%）进行先验电场建模，以及部分研究伴随认知训练，难以分离 tDCS 独立贡献。图示双盲比例 ADHD 70.5%、读写障碍57.1%、ASD 36.3%。因此答案应同时报告已有结果与研究限制。", "plain": "“这些研究未报告严重事件”和“任何儿童、任何条件都安全”是两句话。简答题把研究范围说清楚，再讲限制。", "words": "6,587 次 · 0.94 · 86% · 9/35 · 双盲 · 混合干预", "source": "L8B 第 2–3 页"},
{"id": "8.14", "lesson": 8, "n": 14, "page": 70, "title": "ADHD：冷执行功能、热执行功能与不一致结果", "answer": "执行功能缺陷假说涉及前额叶—纹状体回路及冷执行功能：工作记忆、反应抑制、认知灵活性。动机功能障碍假说涉及腹侧纹状体—vmPFC 奖励回路及热执行功能：延迟折扣与冒险决策。资料靶点分布为左 dlPFC/F3 64.7%、右 IFG/F8 23.5%、vmPFC/Fpz 5.9%。研究例子：Nejati 等 F3 阳极 1 mA、15 分钟改善 N-back 与干扰控制；Soff 等 10 次改善相关症状；Sotnikova 等反应时间缩短却遗漏错误略增。Westwood 等 15 次 rIFG 刺激加训练未显著优于单纯训练；另一 HD-tDCS 研究 0.25 mA 增加虚报、0.5 mA 改善持续注意并维持 4 个月。Nejati 等 2020 平均 8.60 岁研究的 vmPFC 配置改善 BART 和延迟折扣。 另有 Prehn-Kristensen 等（2014）在非快速眼动睡眠期间使用 0.75 Hz 慢波振荡 tDCS 的研究，资料报告ADHD 儿童陈述性记忆提取改善；此处 0.75 Hz 为振荡频率，不能与 mA 电流强度混淆。", "plain": "冷执行功能看“不带明显奖赏情绪时能不能管住任务”；热执行功能看“遇到奖励、冲动和风险时怎样选择”。不同靶点、任务和方案的结果不能一概而论。", "words": "Cold EF · Hot EF · dlPFC · rIFG · vmPFC · 延迟折扣", "source": "L8B 第 3–5 页"},
{"id": "8.15", "lesson": 8, "n": 15, "page": 70, "title": "ASD：E/I 假说、ATEC 与 ToM", "answer": "资料以兴奋/抑制（E/I）失衡作为 ASD 神经病理假说，提及 GABA 抑制不足和谷氨酸兴奋过度；左 dlPFC 为常见靶点（81.8%），也涉及前额叶—小脑回路及 rTPJ/vmPFC。多疗程概述为 10–20 次、每次 20 分钟、1–1.5 mA；具体研究条件不同：Amatachaya 等 5 次 F3 后ATEC 及部分子量表改善并伴 Alpha 升高；Hadoush 等 10 次双额中央刺激；Gómez 等 20 次后部分行为、社交改善维持 6 个月。资料图示 ATEC 下降 25%–35%。ToM 研究平均 10.7 岁，阳极 vmPFC 条件改善，rTPJ 条件与假刺激无显著差异。", "plain": "先分清研究测的是总体症状（ATEC）还是理解他人心理（ToM）。不能因为某一个任务改善，就说所有 ASD 困难都被解决。", "words": "E/I 失衡假说 · GABA · ATEC · ToM · rTPJ · vmPFC", "source": "L8B 第 5–6 页"},
{"id": "8.16", "lesson": 8, "n": 16, "page": 71, "title": "读写障碍：半球平衡配置与跨任务研究", "answer": "资料用左 TPJ/颞上回低活化及右侧代偿解释读写障碍，7 项 RCT 中 5 项（71.4%）采用左阳极—右阴极配置。Costanzo 等研究对象平均 13.2–13.8 岁，18 次、每次 20 分钟、1 mA，并结合阅读任务；资料报告字词准确性、速度和伪词阅读改善，部分效果维持 6 个月，反向极性使错误率恶化。Lazzaro 等单次 TPJ 研究还报告视觉空间注意及相干运动知觉改善；Rahimi 等双侧 STG 研究涉及听觉 ERP 与时间解析度。上述为资料中的研究解释和条件。", "plain": "这里的重点是不同研究怎样针对读写加工环节，以及测量哪些结果。不要把“读得更快”“视觉注意更好”“听觉 ERP 改变”当成同一指标。", "words": "左阳极—右阴极 · 71.4% · Costanzo · 伪词阅读 · 6 个月", "source": "L8B 第 7–8 页"},
{"id": "8.17", "lesson": 8, "n": 17, "page": 71, "title": "状态依赖性、儿童差异与转化边界", "answer": "状态依赖性原则指 tDCS 效应与施加时的认知活动状态有关，资料据此主张与循证教学/认知训练配合，并区分刺激中、刚结束及长期恢复期。儿童较薄颅骨、头皮及 CSF 比例影响电场，成人参数不能直接套用；资料提醒 1 mA 阴极在儿童可能出现兴奋性反转。p.9 另提出0.5–1.0 mA 范围，与前页总述及部分研究剂量应分开记。五项转化局限为缺乏个体滴定、电场建模不足、忽视昼夜节律和睡眠、忽视亚型、缺少真实课堂长期验证。", "plain": "电流、目标区域、儿童特点和当时做的任务都可能影响结果。资料把它称为帮助可塑性的“催化剂”，仍需要教学活动。", "words": "State-Dependency · 个体化 · 电场建模 · 亚型 · 课堂生态", "source": "L8B 第 8–10 页"},
{"id": "8.18", "lesson": 8, "n": 18, "page": 71, "title": "AI、VR/AR 与 LLM 的互补角色", "answer": "资料所引 Voultsiou & Moussiades（2025）涵盖 139 项科技整合研究。VR/AR 提供低焦虑、可重复、刺激可控的练习环境，并支持具身操作；AI 分析行为及生理资料，调整难度和路径；LLM 提供自然语言对话、多语支持、易读文本改写和虚拟人互动。资料列举 VR 在视空间注意、精细动作及语言学习的应用。LLM 也存在幻觉与能力偏见，输出须由了解神经多样性的特教教师审核。", "plain": "VR 负责让学生进入可练习的场景，AI 负责根据表现调整，LLM 负责用语言交流。三个角色可以组合。", "words": "139 项 · VR/AR · 具身认知 · LLM · 幻觉 · 教师审核", "source": "L8B 第 10–11 页"},
{"id": "8.19", "lesson": 8, "n": 19, "page": 72, "title": "按需要选择技术：六类适配例子", "answer": "视觉障碍：AI 眼镜结合 GPS 与机器视觉提供物体识别、导航和音频/触觉支持；听觉障碍：ISENSE 手语虚拟人进行手语与文字转换，振动手环提供提示；肢体障碍：面部特征、眼动与语音指令实现无接触交互。资料图示另举 ASD 使用 VR/虚拟角色支持社交，认知或智力发展困难使用 AAC 及可预测界面支持日常技能，读写或注意困难使用多感官阅读、同步高亮等支持理解。", "plain": "同一个工具可能服务不同学生，但选择理由必须对准具体障碍：看不到、听不到、不能操作、读不懂，支持的方法各不相同。", "words": "ISENSE · 眼动 · AAC · 多感官 · 功能适配", "source": "L8B 第 12 页"},
{"id": "8.20", "lesson": 8, "n": 20, "page": 72, "title": "教师—AI 协同及五项实施限制", "answer": "Teacher-AI Collaboration（TAC）把 AI 定位为辅助备课与行政减负工具，例如拟定 IEP 目标初稿和生成课堂数据仪表盘；教师负责情感理解、道德判断、危机处理及内容审核，保持 Human-in-the-Loop。五项限制是硬件和基础设施成本、VR 眩晕/视觉疲劳、算法偏见与能力歧视、师资准备不足及数字焦虑、虚拟依赖与现实社交脱节。", "plain": "AI 可以帮老师整理和发现线索，但“这个孩子此刻需要什么支持”仍需要教师判断。", "words": "TAC · IEP 初稿 · Human-in-the-Loop · Cybersickness · 算法偏见", "source": "L8B 第 13 页"},
{"id": "8.21", "lesson": 8, "n": 21, "page": 72, "title": "自适应系统三层闭环与四项实施原则", "answer": "三层为感知层（眼动、HRV、点击流）、决策层（AI 判断 ZPD 匹配、心流、过载或无聊）、反馈层（减少噪音、拆分步骤或提高挑战）。四项实施原则为全纳优先设计 Inclusion by Design、教师福祉 Teacher Well-being、虚拟人同理心标准 Empathic Agent Standards、跨领域协作 Cross-Domain Partnerships。设计之初应纳入 WCAG、神经多样性与家庭/权利倡导者参与。", "plain": "先收集线索，再判断学生卡在哪里，最后改变支持，之后继续观察。闭环意味着调整后还要检查是否有效。", "words": "感知层 · 决策层 · 反馈层 · ZPD · 全纳优先设计", "source": "L8B 第 14 页"},
{"id": "8.22", "lesson": 8, "n": 22, "page": 72, "title": "神经数据隐私与五项神经权利", "answer": "资料指出神经数据可能造成过度画像及神经标签化，治理措施包括去标识化、全流程加密、本地/边缘计算、限制第三方传输、规定保存期限及删除。五项神经权利为精神隐私权（Mental Privacy）、精神完整权（Mental Integrity）、心理自主权（Psychological Autonomy）、公平增强权（Fair Access）、反算法偏见权（Protection from Bias）。", "plain": "不仅要问设备能收集什么，还要问谁有权收集、谁能看到、保存多久、学生能不能拒绝。五项权利要记全。", "words": "精神隐私 · 精神完整 · 心理自主 · 公平增强 · 反算法偏见", "source": "L8A 第 19 页；L8B 第 15–16 页"},
{"id": "8.23", "lesson": 8, "n": 23, "page": 73, "title": "认知监控与动态知情同意", "answer": "资料反对强制佩戴脑电头环并按“全班专注力排行榜”奖惩，强调心智自主与适度心智游移的价值。知情同意须解释风险、长期发育未知影响及数据范围；对未成年、认知或语言困难学生，可用视频、图形和社交故事解释。即使监护人已签字，学生持续抓挠、烦躁啼哭等拒绝信号也应被尊重，并保留随时撤回权。", "plain": "家长同意不等于学生之后不能说停。支持学习的监测不该变成盯着脑波处罚学生。", "words": "动态同意 · 身体拒绝 · 随时撤回 · 认知自由", "source": "L8B 第 17 页"},
{"id": "8.24", "lesson": 8, "n": 24, "page": 73, "title": "神经鸿沟与未来课堂", "answer": "神经鸿沟（Neuro-Divide）指昂贵设备及资源差异可能扩大教育机会差距。资料提出低成本开源硬件、公共采购向农村及少数族裔学校倾斜、将 AT 视为教育公共产品，并联系SDG 4 与 10。未来课堂例子包括声学材料、可调照明、柔性或耳戴传感器、边缘 AI 与给教师的温和微提示，目标是可及性与有尊严的参与。", "plain": "技术若只有少数学校买得起，就可能扩大差距。公平不仅是产品做出来，也包括需要的孩子实际用得上。", "words": "Neuro-Divide · 公共产品 · 低成本 · SDG4 与 10", "source": "L8B 第 18 页"},
{"id": "8.25", "lesson": 8, "n": 25, "page": 73, "title": "教师的最终任务：批判评估技术", "answer": "资料要求教师识别神经神话，理解神经可塑性、LTP/LTD 与认知负荷，在科学有效性和教育相关性两个层面评价工具，关注生态效度、技术边界、学生尊严和隐私。选技术的完整问题是：它解决什么功能障碍，证据来自什么样的研究，能否进入实际课程，学生和教师能否持续使用，伦理与公平是否得到保障。", "plain": "老师不需要成为设备推销员，而要能解释“为什么用、帮助了什么、有什么限制”。这是全课各类工具共同的判断方法。", "words": "神经素养 · 生态效度 · 工具边界 · 尊严", "source": "L8A 第 13 页、18–20；L8B 第 19–20 页"},
{"id": "9.1", "lesson": 9, "n": 1, "page": 80, "title": "脑友善课程的出发点与神经神话", "answer": "资料把注意门控、工作记忆限制、组块化、情绪安全、记忆巩固与认知差异作为课程设计依据，强调低情绪威胁、高智力挑战。应识别把学生固定成视觉/听觉/动觉型、左脑/右脑人，以及“大脑只使用 10%”等神经神话；课程依据动态认知准备度提供支持，而非给学生贴固定标签。术语 DMN、TPN、CEN、SN、CLT、LTP、LTD、RPE、SRL、CTML 详见术语表。", "plain": "脑友善不是安排更多“脑训练”，而是让教学方式配合注意、记忆、情绪和当前能力。", "words": "低威胁高挑战 · 认知准备度 · 神经神话 · 多模态", "source": "L9A 第 1–3 页"},
{"id": "9.2", "lesson": 9, "n": 2, "page": 80, "title": "神经可塑性与记忆巩固：资料的解释链", "answer": "赫布定律强调共同活动的神经元连接得到加强。资料将 LTP 解释为反复高频刺激后的传递效率持久增强，涉及 NMDA 激活与 AMPA 上膜；LTD 则涉及低频/异步刺激、AMPA 内吞和传递减弱，并用来解释弱化旧概念。海马体快速进行课堂事件的情境与时空绑定，新皮层进行较慢、分布式的语义存储；资料用间歇及慢波睡眠中的尖波涟漪重放解释系统巩固，提出每课 3–5 分钟“神经消化窗”。这些是本资料的机制解释。", "plain": "学习要有反复激活，也要留出整理和巩固的时间。考题问机制时按资料写 LTP/LTD、海马体和皮层各自的作用。", "words": "Hebbian Theory · LTP · LTD · 海马体 · 系统巩固 · 3–5 分钟", "source": "L9A 第 3–4 页"},
{"id": "9.3", "lesson": 9, "n": 3, "page": 80, "title": "CLT 的三种认知负荷", "answer": "资料给出的工作记忆容量约为 4±1 个信息单元。内在认知负荷（Intrinsic Load）来自材料本身的元素交互复杂度；外在认知负荷（Extraneous Load）来自混乱呈现和无关干扰，应极小化；相关/有效认知负荷（Germane Load）是投入图式构建与深度理解的心理资源，应最适化。课程优化要减少无效消耗，并把资源用于学习，而非把所有负荷都消除。", "plain": "“内容本身难”“材料让人更难懂”“正在努力真正理解”是三件不同的事。最要删的是第二种。", "words": "4±1 · 内在负荷 · 外在负荷 · 有效负荷 · 图式构建", "source": "L9A 第 5–6 页"},
{"id": "9.4", "lesson": 9, "n": 4, "page": 81, "title": "Santioso 研究：减负与回忆数据", "answer": "Santioso 等（2025）资料中的实验组综合使用组块化、双重编码、间隔重复和情绪共鸣材料，对照组为常规混合教学；使用 EEG、负荷量表及记忆测验。资料报告实验组外在负荷显著降低，内在负荷组间无显著差异。即时回忆实验组 79.8、对照组 68.5；实验组延迟回忆82.4。外在负荷与回忆呈负相关，投入与延迟回忆呈正相关；个案 A 报告延迟回忆提高 25%。p.7 的“效应量 33%”未解释指标，按原表述记，不自行换算。", "plain": "材料可以更好懂，同时仍然学同样难的内容。组间实验结果、相关关系和个案反馈要分开讲。", "words": "Santioso · 外在下降 · 内在不变 · 79.8 · 68.5 · 82.4", "source": "L9A 第 5–7 页"},
{"id": "9.5", "lesson": 9, "n": 5, "page": 81, "title": "组块化与双重编码怎样落实", "answer": "资料建议把 45 分钟课分为 3 个 10–12 分钟的核心学习段，每段聚焦 3–4 个概念单元，并留出处理时间。双重编码利用语言与视觉表征的互补，把解释与相关图表对应呈现。应避免屏幕满篇文字又逐字朗读等冗余，以及图文空间分离引起的搜索负担。教案审核矩阵另给“核心概念控制在 3 个组块以内”的要求，应按所在页场景记。", "plain": "一个知识点配一个真正有帮助的图，比很多漂亮但无关的图更有用。分段后要让学生有时间整理，不是切成更多连续灌输。", "words": "Chunking · Dual Coding · 图文对齐 · 冗余 · 3–4 单元", "source": "L9A 第 8 页、19"},
{"id": "9.6", "lesson": 9, "n": 6, "page": 81, "title": "情绪、动机与奖励预测误差", "answer": "资料用杏仁核—海马体—前额叶作为情绪与学习的调控轴，说明动机、注意与记忆相互联系。多巴胺通路包括 VTA 向伏隔核及前额叶投射；奖励预测误差（RPE）指结果与预期的差异，资料强调超出预期的成功反馈所带来的正向信号。课堂转化包括微挑战、即时具体反馈、与课程目标相关的故事、可预测流程和容错环境。情绪元素要承载学习内容，不可成为无关煽情与装饰。", "plain": "任务要让学生有机会成功，并且知道自己哪一步做对了。故事要帮他理解知识，不能只负责把气氛炒热。", "words": "杏仁核—海马体—PFC · VTA · 伏隔核 · RPE · 微挑战", "source": "L9A 第 9 页、12–13"},
{"id": "9.7", "lesson": 9, "n": 7, "page": 82, "title": "情绪设计研究与 CATLM 的边界", "answer": "资料所述 Morkel & Singh（2024）让大学生观看 11 种学习模块首页，每页 9 秒，结合眼动、GSR、瞳孔、面部表情与 SAM 量表。资料指出清晰的顶部—底部结构、14 px 红色/粗体标题、相关插图和留白可引导注意；无关“诱惑细节”增加干扰。CATLM（Cognitive-Affective Theory of Learning with Media）强调情绪与认知相互影响，适度唤醒可促进兴趣和迁移，过度刺激会增加外在负荷。该研究在资料中表现为概念迁移改善，对纯事实回忆的影响有限。", "plain": "有兴趣不等于记住了所有事实。题目若问研究结果，要分清“迁移”与“机械回忆”。14 px是这份资料的设计例子，不是所有页面的统一标准。", "words": "GSR · SAM · 诱惑细节 · CATLM · 迁移 · 适度唤醒", "source": "L9A 第 10–11 页"},
{"id": "9.8", "lesson": 9, "n": 8, "page": 82, "title": "元认知和执行功能支架", "answer": "资料把 dlPFC 与 ACC 联系到目标设定、策略监控、错误检测和自我调节。可用任务清单、自我提问卡和思维路径图把抽象的监控步骤外显化，分担即时记忆负担；任务前设 5 分钟具体微目标，完成后进行自评和策略调整。CEN-STEM 展开页还建议复杂任务前留 2 分钟画思维路径。", "plain": "把“想清楚再做”变成学生看得见、能照着走的步骤。支架的目标是逐渐学会自己检查和调整。", "words": "dlPFC · ACC · Checklist · 微目标 · 自评反思", "source": "L9A 第 13 页、15"},
{"id": "9.9", "lesson": 9, "n": 9, "page": 82, "title": "CEN-STEM：四组十原则必须区分版本", "answer": "全称为 Cognitive and Educational Neuroscience for STEM Education。p.14 主表分四组：教育者知识（1 应对神经神话、2 元认知与执行功能）；情绪动机（3 奖励与动机、4情绪安全、5 情绪参与）；神经适应（6 神经可塑性与针对性学习、7 认知负荷管理、8 大型神经网络相互作用）；积极实践（9 积极参与、10 多重感官/与科技增强学习）。主表还重复印一处 P7“大型参与”，不能自行改号。p.15–16 展开页另列教师素养、执行功能支架、情境故事、安全包容、微步反馈、间隔重复、外在负荷清零、认知生理停顿、主动探究/PBL、多感官整合；P3/P5 对应不一致，详见逐页对照。", "plain": "先背十项内容在解决什么问题；遇到编号题必须看题目指定哪一页。不能把两个版本硬拼成一个标准表。", "words": "CEN-STEM · 四组 · 十原则 · 版本差异", "source": "L9A 第 14–16 页"},
{"id": "9.10", "lesson": 9, "n": 10, "page": 83, "title": "CIRCLE：全称、五层与技能目标", "answer": "p.14 将 CIRCLE 展开为 Child Inclusion: Research into Curriculum, Learning and Education；p.17 侧栏另用 Cognitive、Inclusive、Resilient、Creative 描述学习环境，不能当作同一个英文展开式。五层由内到外为基础层、社会情感层、大脑功能对齐/认知层、学科教学层、技能发展层。图示将层 1 对应原则 1–2，层 2 对应 3–5，层 3 对应 6–8，层 4对应 9–10，层 5 为教育成果；图示更细的层名见比较表。正文技能成果包括认知弹性、自适应问题解决和全纳同伴协作。 p.17 同心图外围还分别列出培养认知韧性、适应性问题解决、认知技能发展、社交情绪发展、共融协作，属于图示的五项成果表述。", "plain": "CEN-STEM 像备课时要考虑的原则清单，CIRCLE 把证据、情绪、认知、教学和最后要培养的能力放在同一个结构里。", "words": "CIRCLE · 基础 · 社会情感 · 认知 · 教学 · 技能", "source": "L9A 第 14 页、17–19"},
{"id": "9.11", "lesson": 9, "n": 11, "page": 83, "title": "DMN 与 TPN 切换，以及教案审核", "answer": "资料将 TPN 与背外侧前额叶、后顶叶的目标导向解题及外部操作相联系，将 DMN 与内侧前额叶、后扣带回和海马体的静息、内省、自由回想相联系。p.17 建议 20 分钟专注后 5 分钟反思；p.16 的 Brain Breaks 另为 15–20 分钟高强度学习后 2–3 分钟低负荷活动，应保留不同情境。教案审核四维为情感安全度、认知负荷度、神经切换度、具身多感官；分别检查低威胁与微成功、组块与去干扰、专注和反思交替、多种感官和操作。", "plain": "学生需要认真做，也需要回头整理。反思、短休息和纯粹长时间分心不是一个概念。", "words": "TPN · DMN · 20＋5 · Brain Breaks · 四维审核", "source": "L9A 第 16–19 页"},
{"id": "9.12", "lesson": 9, "n": 12, "page": 83, "title": "Gomez 自适应混合课程研究", "answer": "资料把自适应定义为根据实时认知表现与进度反馈，动态调整复杂度和支持力度；两项核心机制是提取练习与间隔学习。Gomez 等（2026）采用准实验，将先验知识激活、间隔检索、自适应支架、形成性反馈与元认知反思组合；资料称两组前测等同。后测实验组 82.46、对照组 71.38；延迟保持 79.73 与 65.42。资料报告控制前测后的 ANCOVA 及组别×时间差异显著。投入、动机、SRL、负荷和学习行为结果详见数据表；不能把整套干预的结果归因于其中单一成分。", "plain": "先看学生已经知道什么，再决定下一步怎么教。这个研究比较的是一整套安排，不只是“多做几道题”。", "words": "Gomez · 准实验 · 先验知识 · 间隔检索 · 82.46 · 79.73", "source": "L9A 第 20–22 页"},
{"id": "9.13", "lesson": 9, "n": 13, "page": 84, "title": "提取练习、必要难度与流畅性错觉", "answer": "提取练习（Retrieval Practice）是主动从记忆中重建所学内容，资料与被动重读所造成的熟悉感作对比，建议每课 2–3 次低风险、无分数惩罚的微检索，如一分钟默画脑图和快问快答。必要难度（Desirable Difficulties）要求回想需要一定努力，但能在支架支持下克服；若任务因缺少先备知识和支持而无法完成，就超出了合适难度。资料用神经重构解释记忆增益，其中“永久固化”等是其机制表述。", "plain": "盖住答案还能说出来，才是在练习提取。读得很顺、看着很熟，可能只是“认得答案”，还不是自己能答。", "words": "Retrieval Practice · 低风险 · 必要难度 · 流畅性错觉", "source": "L9B 第 1–2 页"},
{"id": "9.14", "lesson": 9, "n": 14, "page": 84, "title": "自适应六步循环与三类动态路径", "answer": "L9B p.4 图示的六步顺序是动态诊断→教学适配→主动加工→分布提取→形成反馈→监控校准；每一步细节见表。p.3 资料中快速进阶 34%、中度支架 46%、持续支持 20%：前者进入高阶探究，中者加提示与局部解析，后者缩短组块、补前置知识、增加引导检索及个别支持。这是可变化的任务路径，不是固定快慢班。个案 A 前测 56、后测 80、延迟 77，使用微组块、补先备知识、提示检索与面授支持。", "plain": "先找卡点，再给合适任务，练习后看反馈，下一轮再调整。学生可以换路径，不该被一次成绩定型。", "words": "动态诊断 · 教学适配 · 主动加工 · 分布提取 · 形成反馈 · 监控校准", "source": "L9B 第 3–4 页"},
{"id": "9.15", "lesson": 9, "n": 15, "page": 84, "title": "混合教学的功能分配与教师判断", "answer": "认知编排（Cognitive Orchestration）按任务需要分配线上与线下活动。面授承担高社交、高情感、高复杂度任务，包括概念点拨、同伴推理、情绪支持和即时支架；线上承担个体化、异步练习，包括间隔提取、自适应进度、形成性反馈与反思日志。算法与点击流不能替代教师的专业判断，自适应依据认知准备度，而非固定学习风格。", "plain": "不是先决定“哪天线上哪天线下”，而是先决定这件学习任务最需要个人节奏还是现场互动。", "words": "Cognitive Orchestration · 面授 · 异步 · 教师判断", "source": "L9B 第 4–5 页"},
{"id": "9.16", "lesson": 9, "n": 16, "page": 84, "title": "UDL 三网络与三原则", "answer": "UDL 由 CAST 开发，要求从课程设计之初降低学习障碍，使全体多元学习者获得灵活支持。资料映射为识别网络—What—多重表征：以视觉、听觉、触觉、实物和提示帮助理解；策略网络—How—多重表达：允许口语、动作、手偶、画图和搭建展示成果；情感网络—Why—多重参与：通过选择权、真实情境和同伴合作维持兴趣。全纳要有实质认知参与和学习进步，而不只是坐在同一教室。", "plain": "同一个目标，可以换一种看懂的方法、换一种作答的方法，也给学生愿意参与的理由。", "words": "UDL · CAST · What · How · Why · 参与", "source": "L9B 第 5–6 页"},
{"id": "9.17", "lesson": 9, "n": 17, "page": 85, "title": "Jhuo & Chu 行动研究：对象、循环与初始问题", "answer": "资料所述研究在台湾非营利全纳幼儿园进行，全班 30 名 4–6 岁幼儿，其中 5 名发展迟缓；普通教师有 14 年经验，特教人员有 3 年以上资历。跨一学年的三轮行动研究均按Plan→Act→Observe→Reflect。起初问题为特殊幼儿游离活动、低难度教具被隔离储物柜分开、统一目标和抽象提示不适合起点、教师一对一支架负担过高。", "plain": "不是先说孩子“不配合”，而是观察教室和任务哪里让他们难以加入，然后一轮轮改。", "words": "30 名 · 4–6 岁 · 5 名发展迟缓 · 三轮 · 行动研究", "source": "L9B 第 6–7 页"},
{"id": "9.18", "lesson": 9, "n": 18, "page": 85, "title": "Cycle 1：共享材料与多种表达", "answer": "第一轮撤销隔离柜，把改装教具放入公共区角；加入毛线球、手指数字玩具等多感官材料，并允许用黏土、硬币、图章、白板、手势和口语作答。初步观察到原本游荡的幼儿进入区角并模仿同伴。但教师离开后仍会分心或不按规则操作，说明丰富材料和同场参与尚不足以保证独立持续学习；下一步需要可重复语音指引与自律支架。", "plain": "先让孩子能和大家一起接触材料，再解决“老师不在旁边时，能不能继续做”的问题。", "words": "共享区角 · 多重表征 · 多重表达 · 反思迭代", "source": "L9B 第 7–8 页"},
{"id": "9.19", "lesson": 9, "n": 19, "page": 85, "title": "Cycle 2：点读笔与 PAW Patrol 检核表", "answer": "第二轮在绘本和教具旁加入斑马贴纸（Zebra Stickers）与点读笔，提供可自主重复的朗读和规则；资料例子允许幼儿按节奏重播 5–10 次。PAW Patrol 自评表把任务步骤和进度外显化，每完成一项涂笑脸，支持监控与动机。最初表格文字过多造成混乱，修订为图标式步骤并贴在个人柜门上。这里的关键是让说明和检查能重复获取，减少持续依赖教师。", "plain": "点读笔回答“现在要怎么做”，检核表回答“我已经做了什么、下一步是什么”。工具还要根据实际使用继续改。", "words": "Audio Pens · Zebra Stickers · Self-Monitoring · 笑脸反馈 · 图标", "source": "L9B 第 8–9 页"},
{"id": "9.20", "lesson": 9, "n": 20, "page": 85, "title": "Cycle 3：真实情境、立体手偶与同伴支架", "answer": "第三轮用模拟面包店整合数字、数量、货币和 5 以内加减，幼儿触摸面包、数硬币、轮流当顾客与收银员；资料报告发展迟缓幼儿可投入 20 分钟以上。语言区将平面纸偶改为亲手制作的立体黏土手偶，再结合点读和角色扮演；资料例子由描述主角外观进展到概括性格。两人协同教具及购物流程创造模仿、轮流与合作机会，也减轻教师持续一对一监督负担。", "plain": "让抽象的算式和人物特点放进能摸、能做、能交流的事情里。成果要看是否理解和参与，不只是玩得开心。", "words": "Mock Bakery · 黏土手偶 · 具身学习 · 同伴支架 · 20 分钟", "source": "L9B 第 9–10 页"},
{"id": "9.21", "lesson": 9, "n": 21, "page": 86, "title": "ADHD 与 ASD 的具体教案支持", "answer": "资料对 ADHD 建议将 30 分钟独立练习改为 3 个 7–8 分钟微任务，配倒计时、进度标记及即时具体反馈；可使用坐垫或脚部弹力带等低干扰动作支持。对 ASD 强调可预测的视觉流程、稳定环境、较柔和光线、安静角或降噪耳机，以及社交故事和明确规则。其神经递质/回路解释属于资料表述；教学要根据个体反应调整。", "plain": "ADHD 的例子重在把任务和反馈缩小、变清楚；ASD 的例子重在降低不可预测性与感官压力。不能只按诊断名称一刀切。", "words": "微任务 · 进度卡 · 视觉流程 · 感官调节 · 社交故事", "source": "L9B 第 11–12 页"},
{"id": "9.22", "lesson": 9, "n": 22, "page": 86, "title": "读写与数学困难：支持加工过程", "answer": "读写困难可借助语音、TTS、点读、沙盘或黏土字母等多感官输入，字体间距清晰并避免装饰性字体。数学困难部分以顶内沟（IPS）数量加工解释，采用 CPA 顺序：Concrete（实物，如面包、硬币）→Pictorial（图示，如图章与点阵）→Abstract（数字和符号）。具体操作和图示成为进入抽象概念的支架。", "plain": "读写困难时别把所有理解任务都绑在独立读字上；数学先让学生看见和操作数量，再逐步走向符号。", "words": "TTS · 多感官字母 · IPS · CPA · 具体—图示—抽象", "source": "L9B 第 12–13 页"},
{"id": "9.23", "lesson": 9, "n": 23, "page": 86, "title": "三个学科教案例子", "answer": "语文：故事分为 3 个 8 分钟片段，间插 2 分钟同伴活动；以高亮、点读和图片支持理解，让学生用手偶、顺序图或录音表达。数学：模拟面包店中用价格标签、硬币、顾客与收银员角色、图章和笑脸自评学习数量及运算。科学：以营救井中小狗的真实问题情境引入，让学生动手设计、试错与改进，并安排 15 分钟活动后 3 分钟反思。资料科学例子把情境引入标 P5，保留该页编号，不与 p.15 不同编号合并。", "plain": "三个例子都在做同样的事：目标保持清楚，输入、操作、表达和反馈可以有不同路径。", "words": "语文分块 · 面包店数学 · 科学探究 · 多途径表达", "source": "L9B 第 13–14 页"},
{"id": "9.24", "lesson": 9, "n": 24, "page": 87, "title": "评估改革与普特协同五支柱", "answer": "评估应允许不同完成时间与表达方式，例如图示、录音、实物演示及自评反思，重点检查理解而非把同一种书写表现作为唯一入口。普特协同的五支柱为平等互信、共同价值、合理分担工作量、基于数据的双周研讨、共同反思迭代。普通教师提供学科与全班视角，特教人员提供改编和无障碍支持；共同依据课堂记录调整。", "plain": "先确定要考的是理解还是书写。如果考理解，就让表达困难的学生也有机会把理解展示出来。合作也需要明确分工和固定复盘。", "words": "灵活评估 · 平等互信 · 共同价值 · 工作量 · 双周研讨 · 迭代", "source": "L9B 第 15 页"},
{"id": "9.25", "lesson": 9, "n": 25, "page": 87, "title": "文化、环境、教师素养与神经多样性", "answer": "在大班及重视集体秩序的环境中，可保留全班晨会并结合灵活区角，采用熟悉的商店/面包店情境及点读笔、图章等低成本材料。物理环境可用桌椅脚网球或软垫降噪、减少墙面杂乱、清晰分区、设置 3–5 分钟感官退避空间。教师素养三阶为识伪批判、机制理解、教案重构；避免固定学习风格、左右脑类型、关键期后不可逆和快速开脑等神话。学校应支持共同备课与适用材料，尊重神经多样性并让学生理解自己的学习方式。", "plain": "把能调整的教室、材料和流程先调整好。全纳不只是照顾少数孩子，也能让全班更容易学习。", "words": "文化适配 · 低成本 · 环境降负荷 · 三阶素养 · 神经多样性", "source": "L9B 第 16–20 页"}
];
